try{if(globalThis.TRILHA_PUBLIC_CONFIG!=null)deploymentConfig=normalizePublicConfig(globalThis.TRILHA_PUBLIC_CONFIG)}catch{deploymentConfigError='A conexão padrão da Trilha não está válida. Avise a coordenação.'}
if(deploymentConfig)config=deploymentConfig;
else try{const stored=JSON.parse(localStorage.getItem(CONFIG)||'null');if(stored)config=normalizePublicConfig(stored)}catch{}
