function clone(v){return structuredClone(v)}
function validState(s){return s&&['classes','students','assessments','grades','attendance','notices'].every(k=>Array.isArray(s[k]))&&JSON.stringify(s).length<5000000}
icons.refresh='<path d="M20 7v5h-5M4 17v-5h5M6 6a8 8 0 0 1 13 3M18 18A8 8 0 0 1 5 15"/>';
const PROFILE_KEY='trilha-profile-v1';
let myProfile={display_name:'',phone:'',responsibility:'',avatar_data:''}, avatarDraft='', profileExists=false, teamReady=false, workspaceId=null, workspaces=[], teamMembers=[];
const workspacePreference=()=>`trilha-workspace:${config?.url||'local'}:${session?.user.id||'local'}`;
const myName=()=>myProfile.display_name||session?.user.user_metadata?.full_name||'Coordenação';
const ownsWorkspace=()=>!local()&&workspaceId===session?.user.id;
