function resetCoordination(){myProfile={display_name:'',phone:'',responsibility:'',avatar_data:''};avatarDraft='';profileExists=false;teamReady=false;workspaceId=null;workspaces=[];teamMembers=[];resetStudentArea();resetFinance();resetRegistration()}
function databaseFailure(error,operation){const result=new Error(error.message||'Falha ao consultar o banco.');result.code=error.code;result.operationLabel=operation;return result}
async function syncAuthSession(){if(local())return;const {data,error}=await client.auth.getSession();if(error){session=null;resetCoordination();state=fresh();revision=null;throw databaseFailure(error,'atualizar a sessão')}const previous=session?.user.id;session=data.session;if(!session){resetCoordination();state=fresh();revision=null;throw Error('Sua sessão expirou. Entre novamente com seu e-mail e senha.')}if(previous&&previous!==session.user.id){resetCoordination();state=fresh();revision=null}}
function schemaMissing(error){return ['PGRST202','PGRST205','42883','42P01'].includes(error?.code)}
icons.wallet='<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8V5a2 2 0 0 1 2-2h13v2m3 6h-6v5h6"/><circle cx="17" cy="13.5" r=".5"/>';
let financeCharges=[],financeReady=false,financeSnapshot=null,financeStudentFilter='',financeStatusFilter='';
const FINANCE_KEY='trilha-finance-v1';
const paymentMethods={pix:'Pix',cash:'Dinheiro',transfer:'Transferência',card:'Cartão',other:'Outro'};
const financeLabels={paid:'Pago',canceled:'Cancelada',overdue:'Em atraso',today:'Vence hoje',open:'Em aberto'};
function resetFinance(){financeCharges=[];financeReady=false;financeSnapshot=null;financeStudentFilter='';financeStatusFilter=''}
async function loadFinance(){
 financeCharges=[];financeReady=false;
 if(local()){const raw=localStorage.getItem(FINANCE_KEY);financeSnapshot=raw;try{const stored=JSON.parse(raw||'[]');financeCharges=Array.isArray(stored)?stored:[]}catch{financeCharges=[]}return}
 let query=client.from('school_finance_charges').select('id,workspace_owner_id,student_id,student_name,description,amount_cents,due_date,state,paid_on,payment_method,row_version,created_at,updated_at').eq('workspace_owner_id',workspaceId);
 if(appRole!=='coordinator')query=query.eq('student_id',currentPortal().student.id);
 const result=await query.order('due_date',{ascending:true});if(result.error){if(schemaMissing(result.error))return;throw databaseFailure(result.error,'consultar seus pagamentos')}financeCharges=result.data||[];financeReady=true;
}
function chargePill(c){const status=chargeStatus(c);return `<span class="pill finance-status finance-${status}">${financeLabels[status]}</span>`}
function chargeStudentName(c){return state.students.find(s=>s.id===c.student_id)?.name||c.student_name||'Aluno sem cadastro atual'}
function sortedCharges(items){return [...items].sort((a,b)=>(a.state==='open'?0:1)-(b.state==='open'?0:1)||(a.state==='open'?a.due_date.localeCompare(b.due_date):b.due_date.localeCompare(a.due_date)))}
function learnerFinance(p){
 const available=local()||financeReady;
 if(!available)return heading('Meu financeiro','Pagamentos e vencimentos da sua Trilha.')+`<section class="panel">${empty('Informações financeiras ainda não disponíveis','A coordenação está preparando os registros de pagamentos. Consulte a equipe para confirmar sua situação.','','','wallet')}</section>`;
 const items=financeCharges.filter(c=>c.student_id===p.student.id),summary=financeSummary(items);const message={none:['Sem cobranças cadastradas','Nenhuma cobrança ativa foi cadastrada para você.'],late:['Há pagamentos em atraso',summary.overdue.length+' cobrança(s) com vencimento anterior a hoje.'],today:['Seu pagamento vence hoje','Não há cobranças vencidas, mas existe um vencimento para hoje.'],current:['Você está em dia','Não há pagamentos vencidos nos seus registros.']}[summary.status];
 return heading('Meu financeiro','Consulte seus pagamentos, pendências e próximos vencimentos.')+`<section class="finance-overview ${summary.status==='late'?'has-overdue':''}"><span class="finance-overview-icon">${icon(summary.status==='current'?'check':'wallet')}</span><div><span class="eyebrow">MINHA SITUAÇÃO</span><h2>${message[0]}</h2><p>${message[1]}</p></div><span class="pill">${esc(p.class_name)}</span></section><section class="stats finance-stats"><article class="stat"><div class="stat-head">Próximo vencimento<span class="stat-icon">${icon('check')}</span></div><strong class="finance-date">${summary.next?date(summary.next.due_date):'—'}</strong><small>${summary.next?formatMoney(summary.next.amount_cents)+' · '+esc(summary.next.description):'Nenhum próximo vencimento cadastrado'}</small></article>${stat('Total em aberto',formatMoney(summary.openCents),'Inclui vencimentos futuros e pendências','wallet')}${stat('Em atraso',formatMoney(summary.overdueCents),summary.overdue.length+' cobrança(s) vencida(s)','grades')}${stat('Pagamentos confirmados',formatMoney(summary.paidCents),'Confirmações feitas pela coordenação','check')}</section><section class="panel"><div class="panel-header"><h2>Minhas cobranças</h2><span class="pill">${items.length} registros</span></div>${items.length?`<div class="table-wrap"><table class="finance-table learner-finance-table"><thead><tr><th>Descrição</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>Pagamento</th></tr></thead><tbody>${sortedCharges(items).map(c=>`<tr><td><strong>${esc(c.description)}</strong><div class="finance-mobile-detail">${chargePill(c)}${c.state==='paid'?`<span class="finance-method">Pago em ${date(c.paid_on)} · ${paymentMethods[c.payment_method]||'Outro'}</span>`:''}</div></td><td>${date(c.due_date)}</td><td class="finance-amount">${formatMoney(c.amount_cents)}</td><td>${chargePill(c)}</td><td>${c.state==='paid'?`${date(c.paid_on)}<span class="finance-method">${paymentMethods[c.payment_method]||'Outro'}</span>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma cobrança por enquanto','Os valores e os vencimentos aparecerão aqui quando forem cadastrados pela coordenação.','','','wallet')}</section><div class="note">Os pagamentos são confirmados pela coordenação. Se você já pagou e ainda aparece uma pendência, entre em contato com a equipe.</div>`;
}
function financeAdmin(){
 if(financeStudentFilter&&!state.students.some(s=>s.id===financeStudentFilter)&&!financeCharges.some(c=>c.student_id===financeStudentFilter))financeStudentFilter='';
 const scoped=financeCharges.filter(c=>!financeStudentFilter||c.student_id===financeStudentFilter);const items=scoped.filter(c=>!financeStatusFilter||(financeStatusFilter==='open'?c.state==='open':chargeStatus(c)===financeStatusFilter)),s=financeSummary(scoped);const historical=new Map(state.students.map(x=>[x.id,x.name]));for(const c of financeCharges)if(!historical.has(c.student_id))historical.set(c.student_id,c.student_name);
 return heading('Financeiro','Organize as cobranças e confirme os pagamentos dos alunos.',btn('Nova cobrança','finance-new','','plus'))+(!local()&&!financeReady?`<div class="note warn"><strong>Ative o financeiro no Supabase.</strong><p>Execute a atualização SQL para criar as cobranças e liberar a consulta individual dos alunos. Os registros atuais serão preservados.</p><div class="actions">${btn('Baixar atualização SQL','finance-sql','secondary','download')}${btn('Atualizar dados','refresh-access','secondary','refresh')}</div></div>`:'')+`<section class="stats finance-stats">${stat('Recebimentos confirmados',formatMoney(s.paidCents),'Pagamentos registrados pela coordenação','wallet')}${stat('Em aberto',formatMoney(s.openCents),s.open.length+' cobrança(s) a receber','grades')}${stat('Em atraso',formatMoney(s.overdueCents),s.overdue.length+' cobrança(s) vencida(s)','bell')}${stat('Próximo vencimento',s.next?date(s.next.due_date):'—',s.next?formatMoney(s.next.amount_cents):'Nenhum vencimento futuro cadastrado','check')}</section><div class="toolbar finance-filters"><label>Aluno<select id="finance-student-filter">${options([...historical].map(([id,name])=>({id,name})),financeStudentFilter,'Todos os alunos')}</select></label><label>Situação<select id="finance-status-filter">${[['','Todas as situações'],['open','Em aberto'],['overdue','Em atraso'],['today','Vence hoje'],['paid','Pago'],['canceled','Cancelada']].map(([id,name])=>`<option value="${id}" ${id===financeStatusFilter?'selected':''}>${name}</option>`).join('')}</select></label>${btn('Exportar cobranças','finance-export','secondary','download')}</div><section class="panel"><div class="panel-header"><h2>Cobranças dos alunos</h2><span class="pill">${items.length} registros</span></div>${items.length?`<div class="table-wrap"><table class="finance-table"><thead><tr><th>Aluno e cobrança</th><th>Vencimento</th><th>Valor</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${sortedCharges(items).map(c=>`<tr><td><strong>${esc(chargeStudentName(c))}</strong><span class="finance-method">${esc(c.description)}</span></td><td>${date(c.due_date)}</td><td class="finance-amount">${formatMoney(c.amount_cents)}</td><td>${chargePill(c)}${c.state==='paid'?`<span class="finance-method">${date(c.paid_on)} · ${paymentMethods[c.payment_method]||'Outro'}</span>`:''}</td><td><div class="row-actions">${c.state==='open'?`${btn('Registrar pagamento','finance-pay:'+c.id,'secondary','check')}${iconBtn('Editar cobrança','finance-edit:'+c.id,'edit')}${iconBtn('Cancelar cobrança','finance-cancel:'+c.id,'trash')}`:c.state==='paid'?btn('Corrigir pagamento','finance-reopen:'+c.id,'text','edit'):''}${!local()?iconBtn('Histórico da cobrança','finance-audit:'+c.id,'grades'):''}</div></td></tr>`).join('')}</tbody></table></div>`:empty(scoped.length?'Nenhuma cobrança neste filtro':'Comece pelas cobranças dos alunos','Cadastre a descrição, o valor e o vencimento. Cada aluno verá somente os próprios registros.','finance-new','Criar cobrança','wallet')}</section><div class="note">A confirmação é manual, após conferir o recebimento. Vencimentos de hoje ainda não são considerados atrasados. Cobranças canceladas ficam no histórico.</div>`;
}
function bindFinance(){if($('#finance-student-filter'))$('#finance-student-filter').onchange=e=>{financeStudentFilter=e.target.value;render()};if($('#finance-status-filter'))$('#finance-status-filter').onchange=e=>{financeStatusFilter=e.target.value;render()}}
async function persistLocalFinance(charges){if(localStorage.getItem(FINANCE_KEY)!==financeSnapshot)throw Error('As cobranças foram alteradas em outra janela. Atualize antes de salvar.');const raw=JSON.stringify(charges);localStorage.setItem(FINANCE_KEY,raw);financeSnapshot=raw;financeCharges=charges}
async function changeCharge(c,fields){
 if(appRole!=='coordinator')throw Error('Somente a coordenação pode alterar cobranças.');
 if(local()){const current=financeCharges.find(x=>x.id===c.id);if(!current||current.row_version!==c.row_version)throw Error('A cobrança foi alterada. Atualize os dados.');await persistLocalFinance(financeCharges.map(x=>x.id===c.id?{...x,...fields,row_version:x.row_version+1,updated_at:new Date().toISOString()}:x));return}
 const {data,error}=await client.from('school_finance_charges').update({...fields,row_version:c.row_version+1}).eq('id',c.id).eq('workspace_owner_id',workspaceId).eq('row_version',c.row_version).select('id,row_version').maybeSingle();if(error)throw error;if(!data)throw Error('Outro coordenador alterou esta cobrança. Atualize os dados antes de tentar novamente.');await loadFinance();
}
function editCharge(id){
 if(appRole!=='coordinator')return;if(!local()&&!financeReady){toast('Execute a atualização SQL do financeiro primeiro.');return}const c=financeCharges.find(x=>x.id===id);if(c&&c.state!=='open'){toast('Apenas cobranças em aberto podem ser editadas.');return}if(!c&&!state.students.length){toast('Cadastre um aluno antes de criar a cobrança.');return}
 modal(c?'Editar cobrança':'Nova cobrança','O valor e o vencimento ficarão visíveis para o aluno vinculado.',`<div class="form-grid">${c?`<div class="full finance-student-caption"><span class="small muted">Aluno</span><strong>${esc(chargeStudentName(c))}</strong></div>`:`<label class="full">Aluno<select name="student_id" required>${options(state.students,financeStudentFilter)}</select></label>`}<label class="full">Descrição<input name="description" required maxlength="160" placeholder="Ex.: Mensalidade — novembro" value="${esc(c?.description||'')}"></label><label>Valor (R$)<input name="amount" required inputmode="decimal" placeholder="0,00" value="${c?Math.floor(c.amount_cents/100)+','+String(c.amount_cents%100).padStart(2,'0'):''}"></label><label>Vencimento<input name="due_date" type="date" required value="${c?.due_date||financeToday()}"></label></div>`,async values=>{if(busy)return;const description=values.description.trim();if(!description)throw Error('Informe a descrição.');const fields={description,amount_cents:parseChargeAmount(values.amount),due_date:values.due_date};if(!/^\d{4}-\d{2}-\d{2}$/.test(fields.due_date))throw Error('Escolha um vencimento válido.');const student=c?null:state.students.find(s=>s.id===values.student_id);if(!c&&!student)throw Error('Selecione um aluno válido.');busy=true;try{if(c)await changeCharge(c,fields);else if(local()){await persistLocalFinance([{id:uid(),workspace_owner_id:'local',student_id:student.id,student_name:student.name,...fields,state:'open',paid_on:null,payment_method:null,row_version:1,created_at:new Date().toISOString(),updated_at:new Date().toISOString()},...financeCharges])}else{const r=await client.from('school_finance_charges').insert({workspace_owner_id:workspaceId,student_id:student.id,...fields}).select('id').single();if(r.error)throw r.error;await loadFinance()}$('#modal').close();render();toast(c?'Cobrança atualizada.':'Cobrança cadastrada.')}finally{busy=false}})
}
function payCharge(id){const c=financeCharges.find(c=>c.id===id);if(!c||c.state!=='open'||appRole!=='coordinator')return;modal('Registrar pagamento','Confirme somente após conferir o recebimento.',`<div class="payment-summary"><strong>${esc(chargeStudentName(c))}</strong><span>${esc(c.description)}</span><b>${formatMoney(c.amount_cents)}</b><small>Vencimento: ${date(c.due_date)}</small></div><div class="form-grid"><label>Data do pagamento<input name="paid_on" type="date" required max="${financeToday()}" value="${financeToday()}"></label><label>Forma de pagamento<select name="payment_method" required>${Object.entries(paymentMethods).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label></div>`,async values=>{if(busy)return;if(!values.paid_on||values.paid_on>financeToday())throw Error('Informe uma data de pagamento até hoje.');if(!paymentMethods[values.payment_method])throw Error('Selecione a forma de pagamento.');busy=true;try{await changeCharge(c,{state:'paid',paid_on:values.paid_on,payment_method:values.payment_method});$('#modal').close();render();toast('Pagamento confirmado. O aluno já pode consultar a atualização.')}finally{busy=false}})}
function confirmFinanceChange(id,reopen){const c=financeCharges.find(c=>c.id===id);if(!c||appRole!=='coordinator'||(reopen?c.state!=='paid':c.state!=='open'))return;confirmDialog(reopen?'Reabrir esta cobrança?':'Cancelar esta cobrança?',reopen?'O pagamento deixará de ser considerado confirmado e a cobrança voltará a ficar em aberto. Use esta opção para corrigir um registro incorreto.':'A cobrança deixará de contar como pendência e continuará visível no histórico como cancelada.',async()=>{if(busy)return;busy=true;try{await changeCharge(c,{state:reopen?'open':'canceled',paid_on:null,payment_method:null});$('#modal').close();render();toast(reopen?'Cobrança reaberta.':'Cobrança cancelada.')}catch(e){toast(friendly(e))}finally{busy=false}})}
async function financeAudit(id){if(local()||appRole!=='coordinator')return;try{const r=await client.from('school_finance_audit').select('actor_id,operation,previous_data,current_data,changed_at').eq('workspace_owner_id',workspaceId).eq('charge_id',id).order('changed_at',{ascending:false});if(r.error)throw r.error;const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Histórico da cobrança</h2><p>Registro das alterações realizadas pela coordenação.</p>${r.data.map(a=>{const old=a.previous_data,next=a.current_data,label=!old?'Cobrança criada':next.state==='paid'?'Pagamento confirmado':next.state==='canceled'?'Cobrança cancelada':old.state==='paid'?'Pagamento reaberto':'Cobrança atualizada';return `<article class="submission-card"><strong>${label}</strong><p>${formatMoney(next.amount_cents)} · vencimento ${date(next.due_date)}</p><small class="muted">${new Date(a.changed_at).toLocaleString('pt-BR')} · ${esc(teamMembers.find(m=>m.user_id===a.actor_id)?.display_name||'Coordenação')}</small></article>`}).join('')||'<p>Nenhuma alteração registrada.</p>'}`;d.querySelector('.close').onclick=()=>d.close();d.showModal()}catch(e){toast(friendly(e))}}
function exportFinance(){const quote=v=>'"'+String(v??'').replaceAll('"','""').replace(/^[=+@\-\t\r]/,"'$&")+'"';const rows=[['Aluno','Descrição','Valor (R$)','Vencimento','Situação','Data do pagamento','Forma de pagamento'],...financeCharges.filter(c=>!financeStudentFilter||c.student_id===financeStudentFilter).map(c=>[chargeStudentName(c),c.description,(c.amount_cents/100).toFixed(2).replace('.',','),date(c.due_date),financeLabels[chargeStatus(c)],c.paid_on?date(c.paid_on):'',paymentMethods[c.payment_method]||''])];download('financeiro-trilha-'+financeToday()+'.csv','\uFEFF'+rows.map(row=>row.map(quote).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
async function handleFinanceAction(action){const [verb,id]=action.split(':');if(!verb.startsWith('finance-'))return false;if(appRole!=='coordinator')return true;if(verb==='finance-new'||verb==='finance-edit')guardNavigation(()=>editCharge(id));else if(verb==='finance-pay')payCharge(id);else if(verb==='finance-cancel')confirmFinanceChange(id,false);else if(verb==='finance-reopen')confirmFinanceChange(id,true);else if(verb==='finance-audit')await financeAudit(id);else if(verb==='finance-export')exportFinance();else if(verb==='finance-sql'){try{const r=await fetch('./finance.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-financeiro.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}}return true}

let registrationReady=false,registrationEnabled=false,registrationRequests=[],pendingRegistration=null;
const uuidValue=v=>typeof v==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v)?v:null;
function resetRegistration(){registrationReady=false;registrationEnabled=false;registrationRequests=[];pendingRegistration=null}
function registrationWorkspaceHint(){return uuidValue(new URLSearchParams(location.hash.slice(1)).get('inscricao'))||uuidValue(session?.user.user_metadata?.registration_workspace)}
async function loadRegistration(){registrationRequests=[];registrationReady=false;registrationEnabled=false;if(local())return;const r=await client.rpc('school_registration_queue',{workspace_id:workspaceId});if(r.error){if(schemaMissing(r.error))return;throw r.error}const settings=await client.from('school_registration_settings').select('enabled').eq('workspace_owner_id',workspaceId).maybeSingle();if(settings.error)throw settings.error;registrationReady=true;registrationEnabled=!!settings.data?.enabled;registrationRequests=r.data||[]}
async function requestOwnAccess(){const rawName=session.user.user_metadata?.full_name;const name=typeof rawName==='string'&&rawName.trim()?rawName:session.user.email?.split('@')[0]||'Aluno';const r=await client.rpc('school_submit_registration',{requested_name:name,requested_workspace:registrationWorkspaceHint()});if(r.error){if(schemaMissing(r.error))throw Error('Seu acesso ainda não foi liberado. Peça à coordenação para ativar os cadastros ou vincular sua conta.');throw databaseFailure(r.error,'consultar sua solicitação de cadastro')}pendingRegistration=r.data;appRole='pending';studentPortals=[];workspaceId=r.data.workspace_owner_id;return true}
function renderPending(){const declined=pendingRegistration?.state==='declined',inactive=pendingRegistration?.state==='approved';$('#app').innerHTML=`<main class="lock panel pending-access"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="pending-symbol">${icon(declined?'users':'check')}</div><div class="eyebrow">MEU CADASTRO</div><h1>${inactive?'Seu acesso precisa de revisão':declined?'Converse com a coordenação':'Cadastro recebido.'}</h1><p>${inactive?'Seu vínculo de aluno não está ativo. Converse com a coordenação para conferir o acesso.':declined?'Sua solicitação não foi aprovada. Entre em contato com a coordenação para conferir seus dados.':'Seu e-mail está confirmado. A coordenação vai conferir o cadastro e liberar seu acesso às notas, presença, atividades e financeiro.'}</p><div class="pending-identity"><strong>${esc(pendingRegistration?.full_name||'')}</strong><span>${esc(session.user.email)}</span><span class="pill">${inactive?'Acesso não ativo':declined?'Não aprovado':'Aguardando aprovação'}</span></div><div class="actions">${btn('Verificar liberação','refresh-access','','refresh')}${btn('Sair da conta','logout','secondary','logout')}</div></main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action))}
function signupError(error){if(/Signups not allowed|signup.*disabled|signups.*disabled/i.test(error.message||''))return 'O cadastro ainda está desativado. Avise a coordenação para habilitar novos cadastros no Supabase.';if(/rate.limit|too many|security purposes/i.test(error.message||''))return 'Aguarde alguns minutos antes de tentar novamente.';return friendly(error)}
function renderRegister(){if(!client){toast('A coordenação precisa configurar a conexão da Trilha primeiro.');return}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="eyebrow">FAÇA PARTE DA TRILHA</div><h1>Criar minha conta</h1><p>Confirme seu e-mail e aguarde a liberação da coordenação para acessar seus registros.</p><form id="signup-form"><label>Nome completo<input name="full_name" required maxlength="120" autocomplete="name" placeholder="Como você se chama?"></label><label>E-mail<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="Seu e-mail pessoal"></label><label>Senha<input name="password" type="password" required minlength="8" autocomplete="new-password"><span class="field-help">Use pelo menos 8 caracteres.</span></label><label>Confirmar senha<input name="confirmation" type="password" required minlength="8" autocomplete="new-password"></label><p id="signup-error" class="login-error" role="alert"></p><button type="submit" class="btn">Criar conta ${icon('arrow')}</button></form><div class="auth-switch">Já tem uma conta? ${btn('Entrar','auth-login','text')}</div></main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action));$('#signup-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const button=form.querySelector('button[type="submit"]');button.disabled=true;$('#signup-error').textContent='';try{const values=new FormData(form),name=values.get('full_name').trim(),email=values.get('email').trim(),password=values.get('password');if(!name)throw Error('Informe seu nome completo.');if(password!==values.get('confirmation'))throw Error('As senhas não conferem.');const target=await client.rpc('school_registration_target',{requested_workspace:registrationWorkspaceHint()});if(target.error){if(schemaMissing(target.error))throw Error('A coordenação precisa ativar a atualização de cadastro no aplicativo.');throw target.error}if(!target.data)throw Error('Peça à coordenação o link de cadastro desta Trilha.');const result=await client.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname,data:{full_name:name,registration_workspace:target.data}}});if(result.error)throw result.error;if(result.data.session){session=result.data.session;await load();render();return}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="pending-symbol">${icon('check')}</div><h1>Confira seu e-mail.</h1><p>Abra a mensagem de confirmação enviada para <strong>${esc(email)}</strong>. Depois de confirmar, entre na sua conta para enviar o cadastro à coordenação.</p><p class="field-help">Se a mensagem não aparecer, confira a pasta de spam.</p>${btn('Voltar para entrar','auth-login','','arrow')}</main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action))}catch(error){$('#signup-error').textContent=signupError(error);button.disabled=false}}}
function registrationPanel(){const pending=registrationRequests.filter(r=>r.state==='pending');return `<section class="panel"><div class="panel-header"><h2>Solicitações de cadastro</h2><span class="pill">${pending.length} aguardando</span></div><div class="panel-body">${!registrationReady?`<p class="page-help">Ative o cadastro autônomo para as pessoas criarem suas próprias contas. Você aprova o acesso aqui, sem cadastrar cada usuário no Supabase.</p>${btn('Baixar SQL do cadastro','registration-sql','secondary','download')}${btn('Atualizar acesso','refresh-access','text','refresh')}`:!registrationEnabled?`<p class="page-help">Ative o recebimento de solicitações nesta Trilha. Os alunos continuam dependendo da sua aprovação.</p>${ownsWorkspace()?btn('Ativar cadastro','registration-enable','','check'):'<p class="field-help">O responsável principal pode ativar os cadastros.</p>'}`:`<p class="page-help">As pessoas criam a conta e confirmam o e-mail. Ao entrar pela primeira vez, aparecem nesta lista. Confira os dados e vincule cada conta ao aluno correto.</p>${pending.length?pending.map(r=>`<article class="registration-request"><div><strong>${esc(r.full_name)}</strong><span>${esc(r.email)}</span><small>Solicitado em ${new Date(r.created_at).toLocaleDateString('pt-BR')}</small></div><div class="actions">${btn('Aprovar acesso','registration-approve:'+r.id,'secondary','check')}${btn('Recusar','registration-decline:'+r.id,'text')}</div></article>`).join(''):empty('Nenhum cadastro aguardando','As novas solicitações aparecerão aqui depois da confirmação do e-mail e do primeiro login.','','','users')}<div class="actions">${btn('Copiar link de cadastro','registration-link','secondary','arrow')}${btn('Atualizar solicitações','refresh-access','text','refresh')}</div>`}</div></section>`}
function reviewRegistration(id){const r=registrationRequests.find(r=>r.id===id&&r.state==='pending');if(!r)return;modal('Aprovar acesso','Confira o e-mail e escolha o cadastro que pertence a esta pessoa.',`<div class="pending-identity"><strong>${esc(r.full_name)}</strong><span>${esc(r.email)}</span></div><label>Cadastro do aluno<select name="student_id" required>${options(state.students,'','Selecione o aluno correto')}</select></label><div class="note">A aprovação libera somente os registros do aluno escolhido. Não concede acesso à coordenação.</div>${btn('Cadastrar um novo aluno','registration-new-student:'+id,'secondary','plus')}`,async values=>{const result=await client.rpc('school_review_registration',{request_id:id,accept_request:true,student_record_id:values.student_id});if(result.error)throw result.error;await loadAdminLearning();await loadRegistration();$('#modal').close();render();toast('Acesso do aluno aprovado.')})}
async function copyRegistrationLink(){const link=new URL(location.origin+location.pathname);if(!deploymentConfig)link.hash='acesso='+encodeURIComponent(JSON.stringify({url:config.url,key:config.key}));const hash=new URLSearchParams(link.hash.slice(1));hash.set('inscricao',workspaceId);link.hash=hash.toString();try{await navigator.clipboard.writeText(link.href);toast('Link de cadastro copiado.')}catch{const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Link de cadastro</h2><p>Compartilhe com as pessoas que vão se cadastrar.</p><textarea id="registration-link" readonly>${esc(link.href)}</textarea>`;d.querySelector('.close').onclick=()=>d.close();d.showModal();$('#registration-link').select()}}
async function handleRegistrationAction(action){const [verb,id]=action.split(':');if(verb==='auth-register'){renderRegister();return true}if(verb==='auth-login'){renderLogin();return true}if(!verb.startsWith('registration-'))return false;if(appRole==='student'||appRole==='pending'||local())return true;if(verb==='registration-sql'){try{const r=await fetch('./self-registration.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-cadastro-autonomo.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}}else if(verb==='registration-enable'){try{const r=await client.rpc('school_enable_registration',{workspace_id:workspaceId});if(r.error)throw r.error;await loadRegistration();render();toast('Recebimento de cadastros ativado.')}catch(e){toast(friendly(e))}}else if(verb==='registration-approve')reviewRegistration(id);else if(verb==='registration-decline'){confirmDialog('Recusar esta solicitação?','A pessoa não terá acesso aos registros e poderá conversar com a coordenação para conferir os dados.',async()=>{const r=await client.rpc('school_review_registration',{request_id:id,accept_request:false,student_record_id:null});if(r.error){toast(friendly(r.error));return}await loadRegistration();$('#modal').close();render();toast('Solicitação analisada.')})}else if(verb==='registration-link')await copyRegistrationLink();else if(verb==='registration-new-student'){if(!state.classes.length){toast('Crie uma turma em Turmas antes de cadastrar o aluno.');return true}const r=registrationRequests.find(r=>r.id===id);$('#modal').close();editor('student');const input=$('#modal-form [name="name"]');if(input&&r)input.value=r.full_name}return true}

let appRole='coordinator', studentPreview=false, previewStudentId='', learnerPage='home', studentPortals=[], portalIndex=0, learningItems=[], studentLinks=[], portalReady=false;
const LEARNING_KEY='trilha-learning-v1';let learningSnapshot=null;
function resetStudentArea(){appRole='coordinator';studentPreview=false;previewStudentId='';learnerPage='home';studentPortals=[];portalIndex=0;learningItems=[];studentLinks=[];portalReady=false}
function resourceURL(value){try{const u=new URL(value);return u.protocol==='https:'?u.href:''}catch{return ''}}
async function loadStudentIdentity(){const r=await client.rpc('school_student_portals');if(r.error){if(schemaMissing(r.error))throw Error('Seu acesso ainda não foi liberado. Peça à coordenação para vincular sua conta ao cadastro de aluno.');throw databaseFailure(r.error,'consultar sua matrícula')}studentPortals=r.data||[];if(!studentPortals.length){await requestOwnAccess();return}appRole='student';portalReady=true;portalIndex=Math.min(portalIndex,studentPortals.length-1);workspaceId=studentPortals[portalIndex].owner_id}
async function loadAdminLearning(){
 if(appRole==='student')return;
 if(local()){const raw=localStorage.getItem(LEARNING_KEY);learningSnapshot=raw;try{learningItems=JSON.parse(raw||'[]')}catch{learningItems=[]}studentLinks=[];portalReady=false;return}
 const r=await client.from('school_learning_items').select('*').eq('workspace_owner_id',workspaceId).order('created_at',{ascending:false});if(r.error){if(schemaMissing(r.error)){portalReady=false;learningItems=[];studentLinks=[];return}throw r.error}learningItems=r.data||[];
 const links=await client.rpc('school_student_links',{workspace_id:workspaceId});if(links.error)throw links.error;studentLinks=links.data||[];portalReady=true;
}
function previewPortal(){const s=state.students.find(s=>s.id===previewStudentId);if(!s)return null;const grades=state.grades.filter(g=>g.studentId===s.id);return {owner_id:workspaceId,student:{id:s.id,name:s.name,classId:s.classId},class_name:className(s.classId),grades,assessments:state.assessments.filter(a=>a.classId===s.classId||grades.some(g=>g.assessmentId===a.id)),attendance:state.attendance.filter(a=>a.studentId===s.id),notices:state.notices,learning_items:learningItems.filter(i=>i.class_id===s.classId&&i.published),submissions:[]}}
const currentPortal=()=>studentPreview?previewPortal():studentPortals[portalIndex];
const portalAverage=p=>p.grades.length?p.grades.reduce((sum,g)=>sum+Number(g.value),0)/p.grades.length:null;
const portalFrequency=p=>{const calls=p.attendance.filter(a=>a.status!=='excused');return calls.length?calls.filter(a=>a.status==='present').length/calls.length*100:null};
function learnerNotice(n){return `<article class="notice"><span class="pill">${n.category==='important'?'Importante':'Comunicado'}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${date(n.date)} · Coordenação</small></article>`}
function learningCard(i,p){const done=p.submissions.find(s=>s.item_id===i.id&&s.completed);return `<article class="learning-card"><div class="learning-card-top"><span class="learning-type">${icon(i.kind==='activity'?'check':'book')}${i.kind==='activity'?'Atividade opcional':'Material de apoio'}</span>${done?'<span class="pill completed-pill">Concluída</span>':''}</div><h3>${esc(i.title)}</h3><p>${esc(i.body.slice(0,180))}${i.body.length>180?'…':''}</p><div class="learning-card-footer"><span class="small muted">${i.due_date?'Sugestão: '+date(i.due_date):i.kind==='activity'?'No seu ritmo · sem nota':'Para continuar aprendendo'}</span>${btn(i.kind==='activity'?(done?'Ver resposta':'Fazer atividade'):'Abrir material','learner-item:'+i.id,'text','arrow')}</div></article>`}
function learnerHome(p){const average=portalAverage(p),frequency=portalFrequency(p),activities=p.learning_items.filter(i=>i.kind==='activity'),done=p.submissions.filter(s=>s.completed&&activities.some(i=>i.id===s.item_id)).length;return heading('Olá, '+esc(p.student.name.split(' ')[0])+'.','Seu espaço para aprender, acompanhar e continuar crescendo.',btn('Continuar aprendendo','learner-tab:learning','','arrow'))+`<div class="learner-class-line"><span class="pill">${esc(p.class_name)}</span><span>Minha Trilha</span></div><section class="stats">${stat('Minha média',average===null?'—':num(average),'Somente avaliações com nota','grades')}${stat('Minha frequência',frequency===null?'—':num(frequency)+'%','Justificativas fora do cálculo','check')}${stat('Atividades concluídas',done+'/'+activities.length,'Opcionais · não alteram a média','book')}${stat('Avisos',p.notices.length,'Comunicados da coordenação','bell')}</section><div class="learner-home-grid"><section class="panel"><div class="panel-header"><h2>Para esta semana</h2>${btn('Ver tudo','learner-tab:learning','text','arrow')}</div><div class="learning-stack">${p.learning_items.length?p.learning_items.slice(0,2).map(i=>learningCard(i,p)).join(''):empty('Seu próximo passo aparece aqui','Quando a coordenação publicar materiais e atividades para sua turma, você poderá acessá-los neste espaço.','','','book')}</div></section><section class="panel"><div class="panel-header"><h2>Fique por dentro</h2>${btn('Todos os avisos','learner-tab:notices','text','arrow')}</div>${p.notices.length?p.notices.slice(0,3).map(learnerNotice).join(''):empty('Tudo em dia','Os novos comunicados da coordenação aparecerão aqui.','','','bell')}</section></div>`}
function learnerGrades(p){const average=portalAverage(p);return heading('Minhas notas','Acompanhe suas avaliações e os comentários da coordenação.')+`<div class="learner-score"><div><span class="eyebrow">MÉDIA SIMPLES</span><strong>${average===null?'—':num(average)}<small>/ 10</small></strong></div><p>As atividades semanais são opcionais e não entram na sua média.</p></div><section class="panel"><div class="panel-header"><h2>Avaliações</h2><span class="pill">${p.grades.length} notas lançadas</span></div>${p.assessments.length?`<div class="table-wrap"><table><thead><tr><th>Avaliação</th><th>Data</th><th>Nota</th><th>Comentário</th></tr></thead><tbody>${[...p.assessments].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const g=p.grades.find(g=>g.assessmentId===a.id);return `<tr><td><strong>${esc(a.title)}</strong></td><td>${date(a.date)}</td><td><span class="learner-grade">${g?num(g.value):'—'}</span>${g?'':'<span class="small muted"> Aguardando</span>'}</td><td>${esc(g?.note||'—')}</td></tr>`}).join('')}</tbody></table></div>`:empty('Ainda não há avaliações','As avaliações e suas notas aparecerão aqui quando forem cadastradas.','','','grades')}</section>`}
function learnerAttendance(p){const f=portalFrequency(p);return heading('Minha presença','Consulte o histórico das aulas e sua participação.')+`<section class="stats">${stat('Frequência',f===null?'—':num(f)+'%','Presenças ÷ chamadas sem justificativa','check')}${stat('Presenças',p.attendance.filter(a=>a.status==='present').length,'Aulas em que você esteve presente','users')}${stat('Faltas',p.attendance.filter(a=>a.status==='absent').length,'Ausências registradas','book')}${stat('Justificadas',p.attendance.filter(a=>a.status==='excused').length,'Fora do cálculo de frequência','grades')}</section><section class="panel"><div class="panel-header"><h2>Histórico de chamadas</h2></div>${p.attendance.length?`<div class="table-wrap"><table><thead><tr><th>Data da aula</th><th>Situação</th></tr></thead><tbody>${[...p.attendance].sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr><td>${date(a.date)}</td><td><span class="pill attendance-${a.status}">${{present:'Presente',absent:'Falta',excused:'Justificada'}[a.status]}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Sua primeira chamada aparece aqui','Os registros são feitos pela coordenação.','','','check')}</section><p class="page-help">Se encontrar alguma informação incorreta, converse com a coordenação.</p>`}
function learnerLearning(p){return heading('Aprender durante a semana','Materiais e atividades para continuar sua formação no seu ritmo.')+`<div class="note learner-note">${icon('book')}<div><strong>Um convite para aprender.</strong> Todas as atividades desta área são opcionais e não valem nota.</div></div>${p.learning_items.length?`<div class="learning-grid">${p.learning_items.map(i=>learningCard(i,p)).join('')}</div>`:`<section class="panel">${empty('Em breve, novos conteúdos','Os materiais publicados para sua turma aparecerão aqui.','','','book')}</section>`}`}
function learnerProfile(p){avatarDraft=myProfile.avatar_data||'';return heading('Meu perfil','Seus dados pessoais na Trilha Apostólica.')+`<section class="panel learner-profile-panel"><div class="panel-header"><h2>Minha conta</h2><span class="pill">Aluno</span></div><div class="panel-body"><form id="profile-form"><fieldset ${studentPreview?'disabled':''}><div class="profile-photo-row"><div id="photo-preview">${personAvatar(studentPreview?{}:myProfile,studentPreview?p.student.name:myName(),true)}</div><div><label class="btn secondary photo-label">Escolher foto<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button class="btn text" type="button" id="remove-photo">Remover foto</button><p class="field-help">JPG, PNG ou WebP · até 5 MB</p></div></div><div class="form-grid"><label class="full">Nome completo<input name="display_name" required maxlength="120" value="${esc(studentPreview?p.student.name:myProfile.display_name||p.student.name)}"></label><label class="full">E-mail da conta<input type="email" readonly value="${esc(studentPreview?'':session.user.email)}"></label><label>Telefone<input name="phone" type="tel" maxlength="30" autocomplete="tel" value="${esc(studentPreview?'':myProfile.phone)}"></label><input name="responsibility" type="hidden" value="${esc(myProfile.responsibility)}"></div><p id="profile-error" class="form-error" role="alert"></p><div class="form-actions"><button class="btn" type="submit">Salvar perfil</button></div></fieldset></form><div class="note">Turma: <strong>${esc(p.class_name)}</strong>. Alterações na matrícula são feitas pela coordenação.</div></div></section>`}
function renderStudent(){const p=currentPortal();if(!p){if(studentPreview){studentPreview=false;render();return}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><h1>Acesso indisponível</h1><p>Seu cadastro não está vinculado a uma turma com acesso ativo. Converse com a coordenação.</p><div class="actions">${btn('Atualizar acesso','refresh-access','secondary','refresh')}${btn('Sair da conta','logout','','logout')}</div></main>`;bind();return}const nav=[['home','Início','home'],['learning','Aprender','book'],['grades','Notas','grades'],['attendance','Presença','check'],['finance','Financeiro','wallet'],['notices','Avisos','bell']];$('#app').innerHTML=`<div class="shell learner-shell"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><p class="nav-label">MINHA TRILHA</p><nav class="nav" aria-label="Menu do aluno">${nav.map(([key,label,i])=>`<button data-learner-page="${key}" class="${learnerPage===key?'active':''}" ${learnerPage===key?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="profile profile-link" data-learner-page="profile">${personAvatar(studentPreview?{}:myProfile,p.student.name)}<div><strong>${esc(p.student.name)}</strong><span class="muted small">Aluno · Meu perfil</span></div>${icon('arrow')}</button>${studentPreview?'':btn('Sair','logout','text','logout')}</div></aside><main class="main"><header class="topbar"><span class="breadcrumb"><b>Minha Trilha &nbsp; / &nbsp; ${nav.find(n=>n[0]===learnerPage)?.[1]||'Perfil'}</b></span><span class="mobile-brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></span><div class="actions">${studentPreview?'<span class="pill">Prévia</span>':iconBtn('Atualizar meus dados','refresh-access','refresh')}<button class="learner-profile-button" data-learner-page="profile" aria-label="Meu perfil">${personAvatar(studentPreview?{}:myProfile,p.student.name)}</button></div></header><div class="content">${studentPreview?`<div class="preview-bar"><span>${icon('users')}Prévia de <strong>${esc(p.student.name)}</strong> · envios desativados</span>${btn('Voltar à coordenação','learner-exit','secondary','arrow')}</div>`:''}${studentPortals.length>1&&!studentPreview?`<label class="portal-selector">Minha turma<select id="portal-selector">${studentPortals.map((p,i)=>`<option value="${i}" ${i===portalIndex?'selected':''}>${esc(p.class_name)}</option>`).join('')}</select></label>`:''}${({home:learnerHome,learning:learnerLearning,grades:learnerGrades,attendance:learnerAttendance,finance:learnerFinance,notices:p=>heading('Avisos','Comunicados e orientações da coordenação.')+`<section class="panel">${p.notices.length?p.notices.map(learnerNotice).join(''):empty('Tudo em dia','Os avisos da sua turma aparecerão aqui.','','','bell')}</section>`,profile:learnerProfile}[learnerPage]||learnerHome)(p)}<footer class="footer"><span>Trilha Apostólica · Minha Trilha</span>${studentPreview?'':btn('Sair da conta','logout','text','logout')}</footer></div></main></div>`;bind();bindProfile();$$('[data-learner-page]').forEach(b=>b.onclick=()=>guardNavigation(()=>{learnerPage=b.dataset.learnerPage;renderStudent();window.scrollTo(0,0)}));if($('#portal-selector'))$('#portal-selector').onchange=e=>{const index=Number(e.target.value);guardNavigation(()=>{portalIndex=index;workspaceId=studentPortals[index].owner_id;loadFinance().then(renderStudent).catch(e=>toast(friendly(e)))})}}
function openLearnerItem(id){const p=currentPortal(),item=p.learning_items.find(i=>i.id===id);if(!item)return;const existing=p.submissions.find(s=>s.item_id===id);const content=`<span class="pill">${item.kind==='activity'?'Atividade opcional · sem nota':'Material de apoio'}</span><div class="learning-detail">${esc(item.body)}</div>${resourceURL(item.resource_url)?`<a class="btn secondary" href="${esc(resourceURL(item.resource_url))}" target="_blank" rel="noopener noreferrer">Abrir conteúdo ${icon('arrow')}</a>`:''}${item.due_date?`<p class="page-help">Data sugerida: ${date(item.due_date)}. A participação é opcional.</p>`:''}`;if(item.kind==='activity'&&!studentPreview){modal(esc(item.title),'Use este espaço para refletir e registrar seu aprendizado.',content+`<label style="margin-top:22px">Minha resposta <span class="field-help">Opcional · você pode salvar e editar depois.</span><textarea name="response" maxlength="10000" placeholder="O que você aprendeu?">${esc(existing?.response||'')}</textarea></label><label class="completion-label"><input name="completed" type="checkbox" ${existing?.completed!==false?'checked':''}>Marcar como concluída</label>`,async values=>{if(busy)return;busy=true;try{const fields={response:values.response.trim(),completed:values.completed==='on',updated_at:new Date().toISOString()};const table=()=>client.from('school_learning_submissions');let result=existing?await table().update(fields).eq('item_id',id).eq('student_user_id',session.user.id).select('item_id').single():await table().insert({item_id:id,workspace_owner_id:p.owner_id,student_user_id:session.user.id,student_id:p.student.id,...fields}).select('item_id').single();if(result.error?.code==='23505')result=await table().update(fields).eq('item_id',id).eq('student_user_id',session.user.id).select('item_id').single();if(result.error)throw result.error;await load();$('#modal').close();render();toast('Sua atividade foi salva. Ela não altera sua média.')}finally{busy=false}})}else{const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>${esc(item.title)}</h2>${content}${studentPreview&&item.kind==='activity'?'<div class="note">Esta é uma prévia. A resposta e a conclusão ficam disponíveis na conta do aluno.</div>':''}<div class="form-actions"><button class="btn" id="close-learning">Fechar</button></div>`;d.querySelector('.close').onclick=()=>d.close();$('#close-learning').onclick=()=>d.close();d.showModal()}}
function studentAdmin(){return heading('Área do aluno','Acesso individual e conteúdos para continuar aprendendo durante a semana.',btn('Novo conteúdo','learning-new','','plus'))+registrationPanel()+(!local()&&!portalReady?`<div class="note warn"><strong>Ative a área do aluno no banco.</strong><p>Execute a atualização SQL no seu projeto Supabase e clique em Atualizar acesso. Os registros atuais serão preservados.</p><div class="actions">${btn('Baixar atualização SQL','student-sql','secondary','download')}${btn('Atualizar acesso','refresh-access','secondary','refresh')}</div></div>`:'')+`<section class="panel"><div class="panel-header"><h2>Veja como o aluno vai acessar</h2><span class="pill">Conta individual</span></div><div class="panel-body"><p class="page-help">Cada aluno consulta apenas suas notas, sua frequência e os conteúdos publicados para a própria turma.</p><div class="portal-admin-access"><label>Aluno<select id="preview-student">${options(state.students.map(s=>({id:s.id,name:s.name})),previewStudentId,'Selecione um aluno')}</select></label><div class="actions">${btn('Abrir prévia','student-preview','secondary','users')}${btn('Vincular conta','student-link-selected','secondary','plus')}${btn('Copiar link de acesso','student-copy-link','secondary','arrow')}</div></div><p class="field-help">As pessoas podem criar a própria conta e confirmar o e-mail. Aprove as solicitações acima e vincule cada conta ao aluno correto.</p></div></section><section class="panel"><div class="panel-header"><h2>Materiais e atividades</h2><span class="pill">${learningItems.length} conteúdos</span></div><div class="panel-body"><div class="note">As atividades são opcionais e não valem pontos. As notas continuam sendo lançadas apenas nas avaliações.</div>${learningItems.length?`<div class="admin-learning-list">${learningItems.map(i=>`<article class="admin-learning-item"><div><div class="actions"><span class="pill">${i.kind==='activity'?'Atividade opcional':'Material'}</span><span class="pill">${i.published?'Publicado':'Rascunho'}</span></div><h3>${esc(i.title)}</h3><p class="small muted">${esc(className(i.class_id))}${i.due_date?' · '+date(i.due_date):''}</p></div><div class="actions">${i.kind==='activity'?btn('Respostas','learning-responses:'+i.id,'secondary','grades'):''}${iconBtn('Editar conteúdo','learning-edit:'+i.id,'edit')}${iconBtn('Excluir conteúdo','learning-delete:'+i.id,'trash')}</div></article>`).join('')}</div>`:empty('Aprender também durante a semana','Publique textos, links de apoio e atividades opcionais para cada turma.','learning-new','Criar conteúdo','book')}</div></section>`}
async function persistLearning(items){if(local()){if(localStorage.getItem(LEARNING_KEY)!==learningSnapshot)throw Error('Os conteúdos foram alterados em outra janela. Recarregue antes de salvar.');const raw=JSON.stringify(items);localStorage.setItem(LEARNING_KEY,raw);learningSnapshot=raw;learningItems=items}else await loadAdminLearning()}
function editLearning(id){if(!local()&&!portalReady){toast('Execute a atualização SQL da área do aluno primeiro.');return}if(!state.classes.length){toast('Cadastre uma turma antes de publicar conteúdos.');return}const item=learningItems.find(i=>i.id===id)||{};modal(item.id?'Editar conteúdo':'Novo conteúdo','Materiais e atividades semanais para a turma. As atividades não entram na média.',`<div class="form-grid"><label>Tipo<select name="kind"><option value="material">Material de apoio</option><option value="activity" ${item.kind==='activity'?'selected':''}>Atividade opcional</option></select></label><label>Turma<select name="class_id" required>${options(state.classes,item.class_id)}</select></label><label class="full">Título<input name="title" required maxlength="120" value="${esc(item.title||'')}"></label><label class="full">Texto ou enunciado<textarea name="body" maxlength="10000" placeholder="Escreva o material ou a orientação para a atividade…">${esc(item.body||'')}</textarea></label><label class="full">Link de apoio <span class="field-help">Opcional · PDF, vídeo, leitura ou outro recurso HTTPS</span><input name="resource_url" type="url" maxlength="2000" placeholder="https://…" value="${esc(item.resource_url||'')}"></label><label>Data sugerida <span class="field-help">Opcional</span><input name="due_date" type="date" value="${item.due_date||''}"></label><label>Visibilidade<select name="published"><option value="false">Rascunho</option><option value="true" ${item.published?'selected':''}>Publicado para a turma</option></select></label></div>`,async values=>{if(busy)return;const title=values.title.trim();if(!title)throw Error('Informe o título.');if(!state.classes.some(c=>c.id===values.class_id))throw Error('Selecione uma turma válida.');const link=values.resource_url.trim();if(link&&!resourceURL(link))throw Error('Use um link HTTPS válido.');const fields={kind:values.kind,class_id:values.class_id,title,body:values.body.trim(),resource_url:link?resourceURL(link):'',due_date:values.due_date||null,published:values.published==='true',updated_at:new Date().toISOString()};busy=true;try{if(local()){const record={...item,...fields,id:item.id||uid(),created_at:item.created_at||new Date().toISOString()};await persistLearning(item.id?learningItems.map(i=>i.id===item.id?record:i):[record,...learningItems])}else{const table=client.from('school_learning_items');const result=item.id?await table.update(fields).eq('id',item.id).eq('workspace_owner_id',workspaceId).select('id').single():await table.insert({workspace_owner_id:workspaceId,...fields}).select('id').single();if(result.error)throw result.error;await loadAdminLearning()}$('#modal').close();render();toast(fields.published?'Conteúdo publicado para a turma.':'Rascunho salvo.')}finally{busy=false}})}
function studentLinkDialog(id){const s=state.students.find(s=>s.id===id);if(!s){toast('Selecione um aluno.');return}if(local()||!portalReady){toast('Conecte o Supabase e execute a atualização da área do aluno para liberar contas.');return}const existing=studentLinks.find(l=>l.student_id===id);modal('Acesso de '+esc(s.name),'Vincule uma conta individual ao cadastro deste aluno.',`<label>E-mail do aluno<input name="email" type="email" required value="${esc(existing?.email||'')}" placeholder="aluno@exemplo.com"></label><div class="note">O aluno pode criar a própria conta na tela de entrada e confirmar o e-mail. Você também pode aprovar a solicitação diretamente na Área do aluno.</div>${existing?btn('Remover vínculo atual','student-unlink:'+id,'danger','trash'):''}`,async values=>{const {error}=await client.rpc('school_link_student',{workspace_id:workspaceId,student_record_id:id,student_email:values.email.trim()});if(error)throw error;await loadAdminLearning();$('#modal').close();render();toast('Conta vinculada ao aluno.')})}
async function learningResponses(id){const i=learningItems.find(i=>i.id===id);if(!i)return;if(local()){toast('As respostas ficam disponíveis após conectar o Supabase.');return}try{const r=await client.from('school_learning_submissions').select('student_id,response,completed,updated_at').eq('workspace_owner_id',workspaceId).eq('item_id',id).order('updated_at',{ascending:false});if(r.error)throw r.error;const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Respostas</h2><p>${esc(i.title)} · participação opcional, sem nota.</p>${r.data.length?r.data.map(s=>`<article class="submission-card"><strong>${esc(state.students.find(x=>x.id===s.student_id)?.name||'Aluno sem cadastro atual')}</strong><span class="pill">${s.completed?'Concluída':'Em andamento'}</span><p>${esc(s.response||'Sem resposta escrita.')}</p><small class="muted">${new Date(s.updated_at).toLocaleString('pt-BR')}</small></article>`).join(''):empty('Nenhuma resposta por enquanto','As participações dos alunos serão exibidas aqui.','','','grades')}`;d.querySelector('.close').onclick=()=>d.close();d.showModal()}catch(e){toast(friendly(e))}}
async function copyStudentLink(){if(!local()&&!publicKey(config.key)){toast('Configure uma chave pública válida antes de copiar o link.');return}if(local()){toast('Conecte o Supabase antes de compartilhar o acesso.');return}const link=new URL(location.origin+location.pathname);if(!deploymentConfig)link.hash='acesso='+encodeURIComponent(JSON.stringify({url:config.url,key:config.key}));try{await navigator.clipboard.writeText(link.href);toast('Link copiado. Cada aluno entra com sua própria conta.')}catch{const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Link de acesso</h2><p>Compartilhe com os alunos autorizados. O link contém somente a configuração pública do projeto.</p><textarea readonly id="access-link">${esc(link.href)}</textarea>`;d.querySelector('.close').onclick=()=>d.close();d.showModal();$('#access-link').select()}}
function acceptAccessLink(){const params=new URLSearchParams(location.hash.slice(1));if(!params.has('acesso'))return false;try{const incoming=JSON.parse(params.get('acesso'));const u=new URL(incoming.url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/'||u.search||u.hash||!publicKey(incoming.key))throw Error('Configuração inválida.');if(deploymentConfig){if(u.origin!==deploymentConfig.url){$('#app').innerHTML=`<main class="lock panel"><h1>Este link é de outra Trilha</h1><p>Este endereço já possui uma conexão definida pela coordenação.</p><button class="btn" id="use-published-project">Entrar nesta Trilha</button></main>`;$('#use-published-project').onclick=()=>{history.replaceState(null,'',location.pathname+location.search);start()};return true}history.replaceState(null,'',location.pathname+location.search);return false}const apply=()=>{config={url:u.origin,key:incoming.key};localStorage.setItem(CONFIG,JSON.stringify(config));const registrationHint=uuidValue(params.get('inscricao'));history.replaceState(null,'',location.pathname+location.search+(registrationHint?'#inscricao='+registrationHint:''));location.reload()};if(config&&config.url===u.origin&&config.key===incoming.key){history.replaceState(null,'',location.pathname+location.search);return false}if(!config&&!localStorage.getItem(KEY)){apply();return true}$('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><h1>Acessar esta Trilha?</h1><p>Este link conecta ao projeto ${esc(u.hostname)}. Os registros locais serão preservados. Você entrará com sua própria conta.</p><div class="actions"><button class="btn" id="accept-access">Continuar</button><button class="btn secondary" id="cancel-access">Cancelar</button></div></main>`;$('#accept-access').onclick=apply;$('#cancel-access').onclick=()=>{history.replaceState(null,'',location.pathname+location.search);start()};return true}catch{$('#app').innerHTML='<main class="lock panel"><h1>Link inválido</h1><p>Peça à coordenação um novo link de acesso.</p></main>';return true}}
async function handleStudentAction(action){const [verb,id]=action.split(':');if(verb==='learner-tab'){guardNavigation(()=>{learnerPage=id;renderStudent();window.scrollTo(0,0)});return true}if(verb==='learner-item'){openLearnerItem(id);return true}if(verb==='learner-exit'){guardNavigation(()=>{studentPreview=false;page='student-area';render()});return true}if(verb==='student-preview'){const selected=$('#preview-student')?.value||id;if(!state.students.some(s=>s.id===selected)){toast('Selecione um aluno para abrir a prévia.');return true}previewStudentId=selected;studentPreview=true;learnerPage='home';renderStudent();return true}if(verb==='student-link-selected'){studentLinkDialog($('#preview-student')?.value);return true}if(verb==='student-link'){studentLinkDialog(id);return true}if(verb==='student-copy-link'){await copyStudentLink();return true}if(verb==='student-unlink'){const s=state.students.find(s=>s.id===id);$('#modal').close();confirmDialog('Remover acesso do aluno?',`${s?.name||'O aluno'} deixará de entrar nesta área. O cadastro e os registros serão preservados.`,async()=>{const {error}=await client.rpc('school_unlink_student',{workspace_id:workspaceId,student_record_id:id});if(error){toast(friendly(error));return}await loadAdminLearning();$('#modal').close();render();toast('Vínculo removido.')});return true}if(verb==='student-sql'){try{const r=await fetch('./student-area.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-area-do-aluno.sql',await r.text(),'text/plain')}catch(e){toast(friendly(e))}return true}if(verb==='learning-new'||verb==='learning-edit'){guardNavigation(()=>editLearning(id));return true}if(verb==='learning-responses'){await learningResponses(id);return true}if(verb==='learning-delete'){confirmDialog('Excluir conteúdo?','O conteúdo e as respostas correspondentes serão excluídos. As notas das avaliações não serão alteradas.',async()=>{try{if(local())await persistLearning(learningItems.filter(i=>i.id!==id));else{const r=await client.from('school_learning_items').delete().eq('id',id).eq('workspace_owner_id',workspaceId);if(r.error)throw r.error;await loadAdminLearning()}$('#modal').close();render();toast('Conteúdo excluído.')}catch(e){toast(friendly(e))}});return true}return false}

async function loadIdentity(){
 if(local()){try{const p=JSON.parse(localStorage.getItem(PROFILE_KEY)||'null');if(p&&typeof p.display_name==='string')myProfile={...myProfile,...p}}catch{}return}
 const access=await client.rpc('school_access_context');
 if(access.error){if(!schemaMissing(access.error))throw databaseFailure(access.error,'identificar os acessos da sua conta');teamReady=false;workspaceId=session.user.id;return}
 teamReady=true;workspaces=access.data||[];
 if(!workspaces.length)await loadStudentIdentity();
 else{appRole='coordinator';const preferred=localStorage.getItem(workspacePreference());workspaceId=workspaces.find(w=>w.workspace_owner_id===preferred)?.workspace_owner_id||workspaces[0].workspace_owner_id;}
 if(appRole==='pending'){myProfile={display_name:pendingRegistration?.full_name||'',phone:'',responsibility:'',avatar_data:''};profileExists=false;return}
 const profile=await client.from('school_profiles').select('display_name,phone,responsibility,avatar_data').eq('user_id',session.user.id).maybeSingle();
 if(profile.error)throw databaseFailure(profile.error,'consultar seu perfil');
 profileExists=!!profile.data;
 myProfile=profile.data||{display_name:session.user.user_metadata?.full_name||'',phone:'',responsibility:'',avatar_data:''};
}
async function loadTeam(){if(local()||!teamReady){teamMembers=[];return}const {data,error}=await client.rpc('school_team_directory',{workspace_id:workspaceId});if(error)throw error;teamMembers=data||[]}
function profilePage(){
 avatarDraft=myProfile.avatar_data||'';
 const canEdit=local()||teamReady;
 return heading('Perfil','Seu perfil e as pessoas que cuidam da Trilha Apostólica.',local()?'':btn('Atualizar acesso','refresh-access','secondary','check'))+
 `<div class="profile-grid"><section class="panel"><div class="panel-header"><h2>Meu perfil</h2><span class="pill">${local()?'Perfil local':ownsWorkspace()?'Responsável principal':'Coordenador'}</span></div><div class="panel-body"><form id="profile-form"><fieldset ${canEdit?'':'disabled'}><div class="profile-photo-row"><div id="photo-preview">${personAvatar(myProfile,myName(),true)}</div><div><label class="btn secondary photo-label">Escolher foto<input id="profile-photo" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><button type="button" class="btn text" id="remove-photo">Remover foto</button><p class="field-help">JPG, PNG ou WebP · até 5 MB</p></div></div><div class="form-grid"><label class="full">Nome completo<input name="display_name" required maxlength="120" autocomplete="name" placeholder="Como você quer ser identificado?" value="${esc(myProfile.display_name)}"></label><label class="full">E-mail da conta<input type="email" readonly value="${esc(session?.user.email||'')}" placeholder="Disponível ao conectar sua conta"><span class="field-help">Usado para entrar no aplicativo.</span></label><label>Telefone <span class="field-help">Opcional</span><input name="phone" type="tel" autocomplete="tel" maxlength="30" value="${esc(myProfile.phone)}" placeholder="(00) 00000-0000"></label><label>Responsabilidade <span class="field-help">Opcional</span><input name="responsibility" maxlength="120" value="${esc(myProfile.responsibility)}" placeholder="Ex.: Coordenação pedagógica"></label></div><p class="form-error" id="profile-error" role="alert"></p><div class="form-actions"><button class="btn" type="submit">${icon('check')}Salvar perfil</button></div></fieldset></form>${local()?'<div class="note">Este perfil está salvo apenas neste navegador. Conecte sua conta para ter um perfil pessoal e participar da equipe.</div>':!teamReady?`<div class="note warn"><strong>Atualize o banco para liberar perfis e equipe.</strong><p>Baixe o SQL abaixo, execute no SQL Editor do seu projeto Supabase e clique em Atualizar acesso. Seus alunos, notas e presenças serão preservados.</p>${btn('Baixar atualização SQL','download-team-sql','secondary','download')}</div>`:''}</div></section>
 <div><section class="panel"><div class="panel-header"><h2>Equipe de coordenação</h2>${teamReady&&ownsWorkspace()?btn('Adicionar','add-coordinator','secondary','plus'):''}</div>${local()?empty('Cada coordenador com sua conta','Conecte o Supabase e autorize a equipe para compartilhar turmas, notas e presenças.','go-settings','Configurar acesso','users'):!teamReady?empty('Prepare o acesso da equipe','Execute a atualização SQL para liberar os perfis e a coordenação compartilhada.','download-team-sql','Baixar atualização SQL','users'):`<div class="panel-body team-summary"><p class="page-help">Todos nesta equipe podem gerenciar alunos, turmas, avaliações, presenças e avisos. O responsável principal gerencia os acessos.</p>${workspaces.length>1?`<label>Equipe em uso<select id="workspace-selector">${workspaces.map(w=>`<option value="${esc(w.workspace_owner_id)}" ${w.workspace_owner_id===workspaceId?'selected':''}>${esc(w.owner_name)}${w.is_owner?' · Minha equipe':''}</option>`).join('')}</select></label>`:''}</div><div class="team-list">${teamMembers.map(m=>`<article class="team-member"><span class="avatar">${esc(initials(m.display_name))}</span><div class="member-info"><strong>${esc(m.display_name)} ${m.user_id===session.user.id?'<span class="muted small">(você)</span>':''}</strong><span>${esc(m.email)}</span><span class="pill">${m.member_role==='owner'?'Responsável principal':'Coordenador'}</span></div>${ownsWorkspace()&&m.member_role!=='owner'?iconBtn('Remover acesso de '+esc(m.display_name),'remove-coordinator:'+m.user_id,'trash'):''}</article>`).join('')}</div><div class="panel-body"><p class="field-help">Cada pessoa entra com sua própria conta. Use a mesma URL e chave pública do Supabase em cada dispositivo. Também é necessário liberar o acesso a este endereço para cada coordenador.</p></div>`}</section><section class="panel"><div class="panel-header"><h2>Minha conta</h2></div><div class="panel-body"><div class="info-line"><span>Acesso</span><strong>${local()?'Neste dispositivo':'Conta individual'}</strong></div><div class="info-line"><span>Dados da escola</span><strong>${local()?'Locais':teamReady?'Equipe compartilhada':'Seu espaço atual'}</strong></div><p class="page-help">Seu nome e sua foto identificam sua conta. Eles não alteram suas permissões de acesso.</p>${local()?'':btn('Sair da conta','logout','secondary','logout')}</div></section></div></div>`;
}
async function preparePhoto(file){
 if(!file)return;
 if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Escolha uma foto JPG, PNG ou WebP.');
 if(file.size>5*1024*1024)throw Error('A foto deve ter no máximo 5 MB.');
 const objectURL=URL.createObjectURL(file);
 try{const image=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Não foi possível abrir essa foto.'));im.src=objectURL});const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const side=Math.min(image.width,image.height);canvas.getContext('2d').drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,256,256);const data=canvas.toDataURL('image/jpeg',.78);if(!safePhoto(data))throw Error('A foto é muito detalhada. Tente outra imagem.');return data}finally{URL.revokeObjectURL(objectURL)}
}
function photoPreview(){const name=$('#profile-form [name="display_name"]')?.value||myName();$('#photo-preview').innerHTML=personAvatar({avatar_data:avatarDraft},name,true)}
async function storeOnlineProfile(profile){
 const fields={...profile,updated_at:new Date().toISOString()};
 const table=()=>client.from('school_profiles');
 // The account ID is used only when creating a profile; it is never updated.
 let result=await (profileExists?table().update(fields).eq('user_id',session.user.id):table().insert({user_id:session.user.id,...fields})).select('user_id').single();
 // A second tab may have created the profile after it was loaded here.
 if(result.error?.code==='23505')result=await table().update(fields).eq('user_id',session.user.id).select('user_id').single();
 if(result.error)throw result.error;
 profileExists=true;
}
function bindProfile(){
 if(!$('#profile-form'))return;
 $('#profile-form').oninput=()=>dirty=true;
 $('#profile-photo').onchange=async e=>{const input=e.target;input.disabled=true;const submit=$('#profile-form button[type="submit"]');submit.disabled=true;try{const photo=await preparePhoto(input.files[0]);if(photo){avatarDraft=photo;dirty=true;photoPreview()}}catch(e){$('#profile-error').textContent=friendly(e)}finally{input.disabled=false;submit.disabled=false;input.value=''}};
 $('#remove-photo').onclick=()=>{avatarDraft='';dirty=true;photoPreview()};
 $('#profile-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.currentTarget;if(!form.reportValidity())return;const fields=new FormData(form);const profile={display_name:fields.get('display_name').trim(),phone:fields.get('phone').trim(),responsibility:fields.get('responsibility').trim(),avatar_data:avatarDraft};if(!profile.display_name){$('#profile-error').textContent='Informe seu nome.';return}busy=true;const submit=form.querySelector('button[type="submit"]');submit.disabled=true;$('#profile-error').textContent='';try{if(local())localStorage.setItem(PROFILE_KEY,JSON.stringify(profile));else{if(!teamReady)throw Error('Execute a atualização SQL antes de salvar seu perfil.');await storeOnlineProfile(profile)}myProfile=profile;teamMembers=teamMembers.map(m=>m.user_id===session?.user.id?{...m,display_name:profile.display_name}:m);dirty=false;render();toast('Perfil salvo.')}catch(error){$('#profile-error').textContent=friendly(error)}finally{busy=false;submit.disabled=false}};
 if($('#workspace-selector'))$('#workspace-selector').onchange=e=>{const selected=e.target.value;if(!workspaces.some(w=>w.workspace_owner_id===selected))return;guardNavigation(()=>{localStorage.setItem(workspacePreference(),selected);location.reload()});if(dirty)e.target.value=workspaceId};
}
function addCoordinator(){if(!teamReady||!ownsWorkspace())return;modal('Adicionar coordenador','Libere o acesso de uma conta existente às mesmas turmas, notas e presenças da sua equipe.',`<label>E-mail do coordenador<input name="email" type="email" required maxlength="254" autocomplete="email" placeholder="nome@exemplo.com"></label><div class="note">Crie a conta com e-mail confirmado em <strong>Supabase → Authentication → Users</strong> antes de adicioná-la. A senha pertence à pessoa. Este passo não envia convites por e-mail.</div>`,async values=>{const {error}=await client.rpc('school_add_coordinator',{workspace_id:workspaceId,member_email:values.email.trim()});if(error)throw error;await loadTeam();$('#modal').close();render();toast('Coordenador adicionado à equipe.')})}
function removeCoordinator(id){if(!ownsWorkspace()||id===session.user.id)return;const member=teamMembers.find(m=>m.user_id===id);if(!member)return;confirmDialog('Remover acesso da equipe?',`${member.display_name} deixará de acessar os dados desta equipe. A conta e os registros dos alunos serão preservados.`,async()=>{const {error}=await client.rpc('school_remove_coordinator',{workspace_id:workspaceId,member_id:id});if(error){toast(friendly(error));return}await loadTeam();$('#modal').close();render();toast('Acesso à equipe removido.')})}
async function downloadTeamSQL(){try{const r=await fetch('./profiles-team.sql');if(!r.ok)throw Error('Arquivo indisponível.');download('trilha-perfis-e-equipe.sql',await r.text(),'text/plain')}catch(e){toast('Não foi possível baixar a atualização: '+friendly(e))}}
async function refreshAccess(){guardNavigation(async()=>{const wasPending=appRole==='pending';try{await load();render();toast(appRole==='pending'?'Sua solicitação continua aguardando a conferência da coordenação.':wasPending&&appRole==='student'?'Acesso liberado. Bem-vindo à Trilha!':'Dados e acesso atualizados.')}catch(e){if(!session&&!local()){renderLogin(friendly(e));return}if(appRole==='student')renderStudent();else if(appRole==='pending')renderPending();toast((wasPending&&appRole==='student'?'Seu acesso foi liberado. ':'')+friendly(e))}})}
function moreMenu(){const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Mais opções</h2><nav class="more-nav" aria-label="Mais opções">${[['classes','Turmas','book'],['notices','Avisos','bell'],['reports','Acompanhamento','chart'],['student-area','Área do aluno','users'],['finance','Financeiro','wallet'],['settings','Configurações','settings']].map(([id,label,i])=>`<button class="btn secondary" data-target="${id}">${icon(i)}${label}${icon('arrow')}</button>`).join('')}</nav>`;d.querySelector('.close').onclick=()=>d.close();d.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{d.close();guardNavigation(()=>{page=b.dataset.target;viewClass='';search='';render();window.scrollTo(0,0)})});d.showModal()}

async function load(){
 await syncAuthSession();
 await loadIdentity();
 if(appRole==='pending'){state=fresh();revision=null;financeCharges=[];loaded=true;return}
 if(appRole==='student'){state=fresh();revision=null;await loadFinance();loaded=true;return}
 if(local()){const raw=localStorage.getItem(KEY);localSnapshot=raw;if(raw){const v=JSON.parse(raw);if(!validState(v))throw Error('O arquivo local está inválido. Preserve uma cópia antes de continuar.');state=v}else state=fresh();await loadAdminLearning();await loadFinance();loaded=true;return}
 const {data,error}=await client.from('school_workspaces').select('data,revision').eq('owner_id',workspaceId).maybeSingle();if(error)throw databaseFailure(error,'consultar os dados da coordenação');
 if(data){if(!validState(data.data))throw Error('Formato de dados não reconhecido.');state=data.data;revision=data.revision}
 else{const res=await client.from('school_workspaces').insert({owner_id:workspaceId,data:fresh(),revision:1}).select('data,revision').single();if(res.error)throw databaseFailure(res.error,'iniciar os dados da coordenação');state=res.data.data;revision=res.data.revision}
 await loadTeam();
 await loadAdminLearning();
 await loadFinance();
 await loadRegistration();
 loaded=true;
}
async function save(next,message='Salvo com sucesso.'){
 if(appRole==='student'||appRole==='pending'){toast('Esta operação é exclusiva da coordenação.');return false}
 if(busy)return false;busy=true;$$('button[type="submit"], [data-action="save-grades"], [data-action="save-attendance"]').forEach(b=>b.disabled=true);
 try{
  if(!validState(next))throw Error('Os dados não passaram pela validação.');
  if(local()){if(localStorage.getItem(KEY)!==localSnapshot)throw Error('Os dados foram alterados em outra janela. Exporte a cópia e recarregue antes de salvar.');const serialized=JSON.stringify(next);localStorage.setItem(KEY,serialized);localSnapshot=serialized;}
  else{if(!session||revision===null)throw Error('Entre na sua conta para salvar.');const {data,error}=await client.from('school_workspaces').update({data:next,revision:revision+1,updated_at:new Date().toISOString()}).eq('owner_id',workspaceId).eq('revision',revision).select('revision').maybeSingle();if(error)throw error;if(!data)throw Error('Outra janela ou outro coordenador alterou os dados. Recarregue os registros antes de tentar salvar novamente.');revision=data.revision}
  state=next;dirty=false;toast(message);return true;
 }catch(e){toast('Não foi possível salvar: '+friendly(e));return false}finally{busy=false;$$('button:disabled').forEach(b=>b.disabled=false)}
}
function friendly(e){const msg=e.message||String(e);if(/Invalid login credentials/.test(msg))return 'E-mail ou senha incorretos.';if(/Failed to fetch|fetch failed/.test(msg))return 'Confira a conexão com a internet e a configuração do Supabase.';if(/row-level security|permission denied/.test(msg)){const object=msg.match(/permission denied for (?:table|function|schema|relation) [A-Za-z0-9_.]+/i)?.[0];return 'O banco bloqueou '+(e.operationLabel||'esta operação')+(e.code?' (código '+e.code+')':'')+'.'+(object?' Detalhe: '+object+'.':' Verifique a autorização da conta e a atualização SQL.')}return msg}
const className=id=>state.classes.find(c=>c.id===id)?.name||'Sem turma';
const studentsFor=id=>state.students.filter(s=>!id||s.classId===id).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
const studentMean=id=>{const gs=state.grades.filter(g=>g.studentId===id);return gs.length?gs.reduce((n,g)=>n+Number(g.value),0)/gs.length:null};
const frequency=id=>{const a=state.attendance.filter(a=>a.studentId===id&&a.status!=='excused');return a.length?a.filter(a=>a.status==='present').length/a.length*100:null};
const avatar=name=>`<span class="avatar">${esc(initials(name))}</span>`;
function options(items,selected,empty='Selecione'){return `<option value="">${empty}</option>`+items.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.title)}</option>`).join('')}
function empty(title,body,action='',label='',i='book'){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h3>${title}</h3><p>${body}</p>${action?btn(label,action,'', 'plus'):''}</div>`}
function heading(title,desc,actions=''){return `<div class="heading"><div><div class="eyebrow">Trilha Apostólica</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function stat(label,value,sub,i){return `<article class="stat"><div class="stat-head">${label}<span class="stat-icon">${icon(i)}</span></div><strong>${value}</strong><small>${sub}</small></article>`}
function render(){
 if(client&&!session){renderLogin();return}
 if(appRole==='pending'){renderPending();return}
 if(appRole==='student'||studentPreview){renderStudent();return}
 const nav=[['home','Visão geral','home'],['students','Alunos','users'],['classes','Turmas','book'],['grades','Notas','grades'],['attendance','Presença','check'],['notices','Avisos','bell'],['reports','Acompanhamento','chart'],['student-area','Área do aluno','book'],['finance','Financeiro','wallet'],['profile','Perfil','users'],['settings','Configurações','settings']];
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><p class="nav-label">COORDENAÇÃO</p><nav class="nav" aria-label="Menu principal">${nav.map(([id,label,i])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}<button class="mobile-more" data-action="more-menu">${icon('settings')}Mais</button></nav><div class="sidebar-bottom"><button class="profile profile-link" data-page="profile">${personAvatar(myProfile,myName())}<div><strong>${esc(myName())}</strong><span class="muted small">${local()?'Acesso local':ownsWorkspace()?'Responsável principal':'Coordenação'}</span></div>${icon('arrow')}</button></div></aside><main class="main"><header class="topbar"><span class="breadcrumb"><b>${nav.find(n=>n[0]===page)?.[1]||''}</b></span><span class="mobile-brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></span><div class="actions"><span class="date muted">${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span><span class="status"><span class="dot"></span>${local()?'Modo local · neste dispositivo':'Supabase conectado'}</span>${teamReady?iconBtn('Atualizar dados','refresh-access','refresh'):''}</div></header><div class="content">${({home:home,students:students,classes:classes,grades:grades,attendance:attendance,notices:notices,reports:reports,'student-area':studentAdmin,finance:financeAdmin,profile:profilePage,settings:settings}[page]||home)()}<footer class="footer"><span>Trilha Apostólica</span><span>Feito para acompanhar cada passo.</span></footer></div></main></div>`;
 bind();
 bindProfile();
 bindFinance();
}
function home(){
 const allGrades=state.grades;const avg=allGrades.length?num(allGrades.reduce((n,g)=>n+Number(g.value),0)/allGrades.length):'—';const att=state.attendance.filter(a=>a.status!=='excused');const freq=att.length?num(att.filter(a=>a.status==='present').length/att.length*100)+'%':'—';
 return heading('Cada passo importa.','Bem-vindo à coordenação. Acompanhe a jornada da sua escola.',btn('Lançar notas','go-grades','','plus'))+`<section class="stats">${stat('Alunos cadastrados',state.students.length,'Pessoas nesta jornada','users')}${stat('Turmas',state.classes.length,'Grupos de aprendizado','book')}${stat('Média das notas',avg,allGrades.length+' notas lançadas','grades')}${stat('Frequência geral',freq,'Presenças ÷ chamadas sem justificativa','check')}</section><div class="grid-2"><section class="panel"><div class="panel-header"><h2>Suas turmas</h2>${btn('Ver todas','go-classes','text','arrow')}</div>${state.classes.length?`<div class="table-wrap"><table><thead><tr><th>Turma</th><th>Alunos</th><th>Próximo passo</th></tr></thead><tbody>${state.classes.slice(0,4).map(c=>`<tr><td><div class="student-cell"><span class="avatar">${icon('book')}</span><strong>${esc(c.name)}</strong></div></td><td>${studentsFor(c.id).length} alunos</td><td><button class="btn text" data-action="class-grade:${c.id}">Lançar notas ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Sua primeira turma começa aqui','Cadastre uma turma e adicione os alunos para começar a acompanhar as notas e a presença.','new-class','Criar primeira turma')}</section><section class="panel"><div class="panel-header"><h2>Quadro de avisos</h2>${btn('Ver todos','go-notices','text','arrow')}</div>${state.notices.length?state.notices.slice(0,2).map(noticeCard).join(''):empty('Um espaço para os recados','Organize orientações, mudanças de horário e comunicados da escola.','new-notice','Criar aviso','bell')}</section></div>${local()?`<div class="note warn"><strong>Os dados estão salvos somente neste navegador.</strong> Para sincronizar com outros dispositivos, conecte o Supabase em Configurações. Exporte uma cópia antes de trocar de dispositivo. ${btn('Configurar','go-settings','text','arrow')}</div>`:''}`;
}
function students(){
 let list=studentsFor(viewClass).filter(s=>s.name.toLocaleLowerCase('pt-BR').includes(search.toLocaleLowerCase('pt-BR')));
 return heading('Alunos','Cada pessoa, uma história. Organize os alunos da sua escola.',btn('Novo aluno','new-student','','plus'))+`<div class="toolbar"><input class="search" id="search" type="search" placeholder="Buscar aluno pelo nome…" aria-label="Buscar aluno" value="${esc(search)}"><select id="class-filter" aria-label="Filtrar por turma">${options(state.classes,viewClass,'Todas as turmas')}</select></div><section class="panel"><div class="panel-header"><h2>Alunos cadastrados</h2><span class="pill">${list.length} alunos</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Média</th><th>Ações</th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="student-cell">${avatar(s.name)}<strong>${esc(s.name)}</strong></div></td><td><span class="pill">${esc(className(s.classId))}</span></td><td>${studentMean(s.id)===null?'—':num(studentMean(s.id))}</td><td><div class="row-actions">${iconBtn('Acesso do aluno','student-link:'+s.id,'users')}${iconBtn('Editar aluno','edit-student:'+s.id,'edit')}${iconBtn('Excluir aluno','delete-student:'+s.id,'trash')}</div></td></tr>`).join('')}</tbody></table></div>`:empty(search||viewClass?'Nenhum aluno encontrado':'Conheça sua turma','Cadastre seus alunos para lançar notas e registrar a presença.','new-student','Cadastrar aluno','users')}</section>`;
}
function classes(){return heading('Turmas','Organize os grupos que caminham juntos.',btn('Nova turma','new-class','','plus'))+(state.classes.length?`<div class="class-grid">${state.classes.map(c=>`<article class="class-card"><h2>${esc(c.name)}</h2><p>${esc(c.description||'Uma nova etapa da jornada.')}</p><strong>${studentsFor(c.id).length}</strong> <span class="small muted">alunos cadastrados</span><div class="actions">${btn('Lançar notas','class-grade:'+c.id,'text','arrow')}<div style="margin-left:auto" class="actions">${iconBtn('Editar turma','edit-class:'+c.id,'edit')}${iconBtn('Excluir turma','delete-class:'+c.id,'trash')}</div></div></article>`).join('')}</div>`:`<section class="panel">${empty('Vamos criar a primeira turma?','Escolha um nome para a classe. Depois, adicione os alunos que fazem parte dela.','new-class','Criar turma')}</section>`)}
function ensureClass(){if(!viewClass||!state.classes.some(c=>c.id===viewClass))viewClass=state.classes[0]?.id||''}
function grades(){
 ensureClass();const assessments=state.assessments.filter(a=>a.classId===viewClass);if(!assessments.some(a=>a.id===assessmentId))assessmentId=assessments[0]?.id||'';const selected=assessments.find(a=>a.id===assessmentId);const list=studentsFor(viewClass);const count=state.grades.filter(g=>g.assessmentId===assessmentId&&list.some(s=>s.id===g.studentId)).length;
 return heading('Notas','Lance as avaliações e acompanhe o aprendizado de cada aluno.',btn('Nova avaliação','new-assessment','','plus'))+`<div class="toolbar"><div class="actions"><select id="class-filter" aria-label="Turma">${options(state.classes,viewClass,'Selecione uma turma')}</select><select id="assessment-filter" aria-label="Avaliação">${options(assessments,assessmentId,'Selecione uma avaliação')}</select></div><div class="actions">${selected?btn('Editar avaliação','edit-assessment:'+selected.id,'secondary','edit'):''}${selected?btn('Excluir','delete-assessment:'+selected.id,'secondary','trash'):''}</div></div>`+(!viewClass?`<section class="panel">${empty('Primeiro, crie uma turma','As notas ficam organizadas por turma e avaliação.','new-class','Criar turma')}</section>`:!selected?`<section class="panel">${empty('O primeiro registro de aprendizado','Crie uma avaliação com título e data. As notas vão de 0 a 10.','new-assessment','Criar avaliação','grades')}</section>`:!list.length?`<section class="panel">${empty('Esta turma ainda não tem alunos','Adicione os alunos da turma para começar a lançar as notas.','new-student','Adicionar aluno','users')}</section>`:`<section class="panel"><div class="panel-header"><div><h2>${esc(selected.title)}</h2><p class="small muted" style="margin:7px 0 0">${date(selected.date)} · ${esc(className(viewClass))}</p></div><span class="pill">${count} de ${list.length} notas</span></div><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Nota · 0 a 10</th><th>Observação</th></tr></thead><tbody>${list.map(s=>{const g=state.grades.find(g=>g.studentId===s.id&&g.assessmentId===assessmentId);return `<tr><td><div class="student-cell">${avatar(s.name)}<strong>${esc(s.name)}</strong></div></td><td><input class="grade-input" data-grade="${s.id}" aria-label="Nota de ${esc(s.name)}" type="number" inputmode="decimal" min="0" max="10" step="0.1" placeholder="—" value="${g?.value??''}"></td><td><input data-grade-note="${s.id}" aria-label="Observação sobre ${esc(s.name)}" maxlength="300" placeholder="Opcional" value="${esc(g?.note||'')}"></td></tr>`}).join('')}</tbody></table></div></section><div class="saving-bar"><span>Em branco = sem nota. Zero é uma nota válida.</span>${btn('Salvar notas','save-grades','','check')}</div><p class="page-help">As médias usam todas as notas lançadas, com o mesmo peso. Atividades semanais opcionais não entram na média.</p>`);
}
function attendance(){ensureClass();const list=studentsFor(viewClass);return heading('Presença','Registre a chamada e acompanhe quem está caminhando com você.')+`<div class="toolbar"><div class="actions"><select id="class-filter" aria-label="Turma">${options(state.classes,viewClass,'Selecione uma turma')}</select><input id="attendance-date" type="date" aria-label="Data da chamada" value="${attendanceDate}" required></div>${list.length?btn('Marcar todos presentes','all-present','secondary','check'):''}</div>`+(!viewClass?`<section class="panel">${empty('Comece por uma turma','Cadastre uma turma e seus alunos antes de registrar a chamada.','new-class','Criar turma')}</section>`:!list.length?`<section class="panel">${empty('Adicione os alunos da turma','A chamada aparecerá aqui assim que os primeiros alunos forem cadastrados.','new-student','Adicionar aluno','users')}</section>`:`<section class="panel"><div class="panel-header"><h2>Chamada · ${date(attendanceDate)}</h2><span class="pill">${list.length} alunos</span></div><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Situação</th></tr></thead><tbody>${list.map(s=>{const a=state.attendance.find(a=>a.studentId===s.id&&a.classId===viewClass&&a.date===attendanceDate);return `<tr><td><div class="student-cell">${avatar(s.name)}<strong>${esc(s.name)}</strong></div></td><td><div class="attendance-buttons" data-attendance="${s.id}">${[['present','Presente'],['absent','Falta'],['excused','Justificada']].map(([status,label])=>`<button data-status="${status}" class="${a?.status===status?'selected-'+status:''}" aria-pressed="${a?.status===status}">${label}</button>`).join('')}${a?`<button data-status="clear" title="Limpar registro" aria-label="Limpar registro de ${esc(s.name)}">×</button>`:''}</div></td></tr>`}).join('')}</tbody></table></div></section><div class="saving-bar"><span>Aluno sem marcação continua sem registro.</span>${btn('Salvar chamada','save-attendance','','check')}</div><p class="page-help">Faltas justificadas ficam no histórico e não entram no cálculo da frequência.</p>`)}
function noticeCard(n){return `<article class="notice"><span class="pill">${n.category==='important'?'Importante':'Comunicado'}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${date(n.date)} · Coordenação</small>${page==='notices'?`<div class="actions" style="float:right">${iconBtn('Editar aviso','edit-notice:'+n.id,'edit')}${iconBtn('Excluir aviso','delete-notice:'+n.id,'trash')}</div>`:''}</article>`}
function notices(){return heading('Quadro de avisos','Recados e orientações para a comunidade da escola.',btn('Novo aviso','new-notice','','plus'))+`<div class="note">Os avisos publicados ficam visíveis para a coordenação e para os alunos com acesso liberado.</div><section class="panel">${state.notices.length?state.notices.map(noticeCard).join(''):empty('Todo mundo na mesma página','Registre mudanças de horário, orientações sobre uso do celular e outros recados.','new-notice','Publicar primeiro aviso','bell')}</section>`}
function reports(){const list=studentsFor(viewClass);return heading('Acompanhamento','Uma visão do aprendizado e da participação.',btn('Exportar CSV','export-csv','secondary','download'))+`<div class="toolbar"><select id="class-filter" aria-label="Turma">${options(state.classes,viewClass,'Todas as turmas')}</select></div><section class="panel"><div class="panel-header"><h2>Jornada dos alunos</h2><span class="pill">${list.length} alunos</span></div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Média simples</th><th>Notas</th><th>Faltas</th><th>Frequência</th></tr></thead><tbody>${list.map(s=>{const a=studentMean(s.id),f=frequency(s.id);return `<tr><td><div class="student-cell">${avatar(s.name)}<strong>${esc(s.name)}</strong></div></td><td>${esc(className(s.classId))}</td><td>${a===null?'—':num(a)}</td><td>${state.grades.filter(g=>g.studentId===s.id).length}</td><td>${state.attendance.filter(a=>a.studentId===s.id&&a.status==='absent').length}</td><td>${f===null?'—':`${num(f)}% <div class="progress"><span style="width:${f}%"></span></div>`}</td></tr>`}).join('')}</tbody></table></div>`:empty('O acompanhamento começa com os alunos','Cadastre os alunos e registre as primeiras avaliações e chamadas.','new-student','Cadastrar aluno','chart')}</section><div class="note">A média é simples, considerando somente as notas lançadas. A frequência considera presenças e faltas; registros justificados são excluídos do denominador.</div>`}
function settings(){return heading('Configurações','Sua escola, seus dados e o aplicativo sempre à mão.')+`<div class="settings-grid"><section class="panel"><div class="panel-header"><h2>Banco de dados · Supabase</h2><span class="pill">${local()?'Não conectado':'Conectado'}</span></div><div class="panel-body"><p class="page-help">Use um projeto próprio para acessar os mesmos dados no iPhone e no computador. O login é exclusivo da coordenação.</p>${local()?`<form id="config-form"><div class="form-grid"><label class="full">URL do projeto<input name="url" type="url" required placeholder="https://seu-projeto.supabase.co"></label><label class="full">Chave pública (publishable ou anon)<input name="key" required autocomplete="off" placeholder="sb_publishable_…"><span class="field-help">Use somente a chave pública. Nunca informe a chave secreta ou service_role.</span></label></div><div class="form-actions">${btn('Como configurar','setup-help','secondary')}<button class="btn" type="submit">Conectar Supabase</button></div><p class="form-error" id="config-error" role="alert"></p></form>`:`<div class="connection">${esc(config.url)}<br>${esc(session?.user.email||'')}</div><div class="actions">${btn('Sair da conta','logout','secondary','logout')}${deploymentConfig?'':btn('Desconectar projeto','disconnect','secondary')}</div><p class="page-help">${deploymentConfig?'Conexão padrão da Trilha, configurada na publicação. Os participantes não precisam informar chaves.':'Desconectar não apaga os dados do Supabase.'}</p>`}<div class="note">O projeto precisa ter o esquema SQL aplicado e seu usuário autorizado antes do primeiro acesso. ${btn('Baixar SQL','download-sql','text','download')}</div></div></section><section class="panel"><div class="panel-header"><h2>No seu iPhone</h2><span class="pill">Aplicativo instalável</span></div><div class="panel-body"><p class="page-help">Abra o endereço do aplicativo no <strong>Safari</strong>.</p><ol class="install-steps"><li>Toque em <strong>Compartilhar</strong>.</li><li>Escolha <strong>Adicionar à Tela de Início</strong>.</li><li>Confirme o nome e toque em <strong>Adicionar</strong>.</li></ol><div class="note">A interface pode abrir sem internet depois do primeiro acesso. A gravação no Supabase exige conexão.</div></div></section><section class="panel"><div class="panel-header"><h2>Cópias e exportação</h2></div><div class="panel-body"><p class="page-help">Exporte alunos, turmas, avaliações, notas, chamadas e avisos antes de trocar de navegador. Os conteúdos semanais, suas respostas e o financeiro não fazem parte desta cópia. As cobranças podem ser exportadas em Financeiro. O arquivo contém os nomes e os registros dos alunos; guarde-o com cuidado.</p><div class="actions">${btn('Exportar cópia','export-backup','secondary','download')}${btn('Importar cópia','import-backup','secondary')}${btn('Planilha de acompanhamento','export-csv','secondary','chart')}</div><input type="file" id="backup-file" accept="application/json,.json" hidden></div></section><section class="panel"><div class="panel-header"><h2>Sobre esta versão</h2><span class="pill">1.0</span></div><div class="panel-body"><div class="info-line"><span>Nome</span><strong>Trilha Apostólica</strong></div><div class="info-line"><span>Perfil</span><strong>Coordenação</strong></div><div class="info-line"><span>Notas</span><strong>0 a 10 · média simples</strong></div><p class="page-help">Identidade visual oficial da Trilha Apostólica, com a logo da marca e tema em preto, branco e cinza.</p>${btn('Ver acompanhamento','go-reports','text','arrow')}</div></section></div>`}
function modal(title,desc,body,onSubmit){const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>${title}</h2><p>${desc}</p><form id="modal-form">${body}<p id="modal-error" class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn secondary" id="cancel-modal">Cancelar</button><button type="submit" class="btn">Salvar</button></div></form>`;d.querySelector('.close').onclick=()=>d.close();$('#cancel-modal').onclick=()=>d.close();$('#modal-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=e.currentTarget;if(!form.reportValidity())return;try{await onSubmit(Object.fromEntries(new FormData(form)))}catch(e){$('#modal-error').textContent=friendly(e)}};d.querySelectorAll('[data-action]').forEach(b=>{b.type='button';b.onclick=()=>handle(b.dataset.action)});d.showModal()}
function editor(kind,id){
 if(kind==='student'&&!state.classes.length){toast('Crie uma turma antes de cadastrar alunos.');editor('class');return}
 const collection={student:'students',class:'classes',assessment:'assessments',notice:'notices'}[kind];const record=state[collection].find(x=>x.id===id)||{};
 const fields={class:`<div class="form-grid"><label class="full">Nome da turma<input name="name" required maxlength="80" value="${esc(record.name||'')}" placeholder="Ex.: Fundamentos da fé"></label><label class="full">Descrição <span class="field-help">Opcional · horário, etapa ou observação</span><input name="description" maxlength="200" value="${esc(record.description||'')}" placeholder="Ex.: Domingos, às 9h"></label></div>`,student:`<div class="form-grid"><label class="full">Nome completo<input name="name" required maxlength="120" value="${esc(record.name||'')}" placeholder="Nome do aluno"></label><label class="full">Turma<select name="classId" required>${options(state.classes,record.classId||viewClass)}</select></label><label class="full">Observações<textarea name="notes" maxlength="1000" placeholder="Opcional">${esc(record.notes||'')}</textarea></label></div>`,assessment:`<div class="form-grid"><label class="full">Título da avaliação<input name="title" required maxlength="100" value="${esc(record.title||'')}" placeholder="Ex.: Avaliação — módulo 1"></label><label>Turma<select name="classId" required ${record.id?'disabled':''}>${options(state.classes,record.classId||viewClass)}</select></label><label>Data<input name="date" type="date" required value="${record.date||today()}"></label></div><div class="note">Esta avaliação terá notas de 0 a 10 e entrará na média simples.</div>`,notice:`<div class="form-grid"><label class="full">Título<input name="title" required maxlength="100" value="${esc(record.title||'')}" placeholder="Qual é o recado?"></label><label class="full">Mensagem<textarea name="body" required maxlength="5000" placeholder="Escreva as orientações…">${esc(record.body||'')}</textarea></label><label>Tipo<select name="category"><option value="general">Comunicado</option><option value="important" ${record.category==='important'?'selected':''}>Importante</option></select></label><label>Data<input name="date" type="date" required value="${record.date||today()}"></label></div>`};
 const names={class:'turma',student:'aluno',assessment:'avaliação',notice:'aviso'};
 if(kind==='assessment'&&!state.classes.length){toast('Crie uma turma antes de cadastrar uma avaliação.');editor('class');return}
 modal(`${id?'Editar':'Novo cadastro de'} ${names[kind]}`,{class:'Um grupo para aprender e crescer junto.',student:'Cadastre os dados essenciais para acompanhar este aluno.',assessment:'Organize o lançamento de notas por turma e data.',notice:'Prepare um comunicado para o quadro de avisos.'}[kind],fields[kind],async values=>{
  for(const k in values)values[k]=values[k].trim();if(('name'in values&&!values.name)||('title'in values&&!values.title)||('body'in values&&!values.body))throw Error('Preencha os campos obrigatórios.');
  const next=clone(state), obj={...record,...values,id:record.id||uid()};if(kind==='assessment'&&record.id)obj.classId=record.classId;if(['student','assessment'].includes(kind)&&!state.classes.some(c=>c.id===obj.classId))throw Error('Selecione uma turma válida.');
  const index=next[collection].findIndex(x=>x.id===obj.id);if(index>=0)next[collection][index]=obj;else kind==='notice'?next[collection].unshift(obj):next[collection].push(obj);
  if(await save(next)){if(kind==='assessment'){viewClass=obj.classId;assessmentId=obj.id;page='grades'}$('#modal').close();render()}
 });
}
function confirmDialog(title,body,action){const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>${title}</h2><p>${esc(body)}</p><div class="form-actions"><button class="btn secondary" id="cancel-modal">Cancelar</button><button class="btn danger" id="confirm-action">Confirmar</button></div>`;d.querySelector('.close').onclick=()=>d.close();$('#cancel-modal').onclick=()=>d.close();$('#confirm-action').onclick=async()=>{if(busy)return;$('#confirm-action').disabled=true;try{await action()}finally{if($('#confirm-action'))$('#confirm-action').disabled=false}};d.showModal()}
function deletion(kind,id){
 if(kind==='student'&&financeCharges.some(c=>c.student_id===id&&c.state==='open')){toast('Este aluno possui cobranças em aberto. Confirme ou cancele essas cobranças antes de excluir o cadastro.');return}
 const map={student:'students',class:'classes',assessment:'assessments',notice:'notices'};if(kind==='class'&&(state.students.some(s=>s.classId===id)||state.assessments.some(a=>a.classId===id)||state.attendance.some(a=>a.classId===id))){toast('Esta turma possui alunos ou registros. Preserve o histórico; exclua apenas turmas vazias.');return}
 confirmDialog('Excluir este registro?',kind==='student'?'O aluno e todas as suas notas e presenças serão excluídos. Exporte uma cópia antes, se precisar preservar o histórico.':kind==='assessment'?'A avaliação e todas as suas notas serão excluídas.':'Este registro será excluído.',async()=>{const next=clone(state);next[map[kind]]=next[map[kind]].filter(x=>x.id!==id);if(kind==='student'){next.grades=next.grades.filter(x=>x.studentId!==id);next.attendance=next.attendance.filter(x=>x.studentId!==id)}if(kind==='assessment')next.grades=next.grades.filter(x=>x.assessmentId!==id);if(await save(next,'Registro excluído.')){$('#modal').close();render()}})
}
async function saveGrades(){const next=clone(state);for(const input of $$('[data-grade]')){if(!input.reportValidity())return;const studentId=input.dataset.grade,raw=input.value.trim();next.grades=next.grades.filter(g=>!(g.studentId===studentId&&g.assessmentId===assessmentId));if(raw==='')continue;const value=Number(raw);if(!Number.isFinite(value)||value<0||value>10){toast('Informe uma nota entre 0 e 10.');return}next.grades.push({studentId,assessmentId,value,note:$(`[data-grade-note="${studentId}"]`).value.trim()})}if(await save(next,'Notas salvas.'))render()}
async function saveAttendance(){if(!attendanceDate){toast('Escolha a data da chamada.');return}const next=clone(state);for(const row of $$('[data-attendance]')){const studentId=row.dataset.attendance;next.attendance=next.attendance.filter(a=>!(a.studentId===studentId&&a.classId===viewClass&&a.date===attendanceDate));const selected=row.querySelector('[aria-pressed="true"]');if(selected&&selected.dataset.status!=='clear')next.attendance.push({studentId,classId:viewClass,date:attendanceDate,status:selected.dataset.status})}if(await save(next,'Chamada salva.'))render()}
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(){download('trilha-apostolica-'+today()+'.json',JSON.stringify({app:'trilha-apostolica',version:1,exportedAt:new Date().toISOString(),data:state},null,2),'application/json');toast('Cópia exportada.')}
function exportCSV(){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const rows=[['Aluno','Turma','Média simples','Notas lançadas','Faltas','Frequência (%)'],...studentsFor(viewClass).map(s=>[s.name,className(s.classId),studentMean(s.id)===null?'':num(studentMean(s.id)),state.grades.filter(g=>g.studentId===s.id).length,state.attendance.filter(a=>a.studentId===s.id&&a.status==='absent').length,frequency(s.id)===null?'':num(frequency(s.id))])];download('acompanhamento-trilha-'+today()+'.csv','\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
async function importBackup(file){if(!file)return;try{if(file.size>5000000)throw Error('Arquivo grande demais.');const data=JSON.parse(await file.text());if(data.app!=='trilha-apostolica'||data.version!==1||!validState(data.data))throw Error('Cópia inválida ou de uma versão incompatível.');validateImport(data.data);confirmDialog('Restaurar esta cópia?',`A cópia tem ${data.data.students.length} alunos e ${data.data.classes.length} turmas. Ela substituirá os registros atuais deste ${local()?'navegador':'espaço de coordenação no Supabase'}. Exporte seus registros atuais antes de continuar.`,async()=>{if(await save(data.data,'Cópia restaurada.')){$('#modal').close();render()}})}catch(e){toast('Não foi possível importar: '+friendly(e))}}
function validateImport(s){for(const kind of ['classes','students','assessments','notices']){const ids=new Set();for(const r of s[kind]){if(!r||typeof r.id!=='string'||ids.has(r.id))throw Error('Há registros inválidos ou repetidos.');ids.add(r.id);if(kind==='classes'||kind==='students'){if(typeof r.name!=='string'||!r.name.trim())throw Error('Nome inválido.')}else if(typeof r.title!=='string'||!r.title.trim())throw Error('Título inválido.')}}const stu=new Set(s.students.map(x=>x.id)),cls=new Set(s.classes.map(x=>x.id)),ass=new Set(s.assessments.map(x=>x.id));for(const r of [...s.students,...s.assessments])if(!cls.has(r.classId))throw Error('Turma ausente na cópia.');const unique=new Set();for(const g of s.grades){const k=g.studentId+':'+g.assessmentId;if(!stu.has(g.studentId)||!ass.has(g.assessmentId)||typeof g.value!=='number'||g.value<0||g.value>10||unique.has(k))throw Error('Nota inválida ou repetida na cópia.');unique.add(k)}for(const a of s.attendance){const k=a.studentId+':'+a.classId+':'+a.date;if(!stu.has(a.studentId)||!cls.has(a.classId)||!/^\d{4}-\d{2}-\d{2}$/.test(a.date)||!['present','absent','excused'].includes(a.status)||unique.has(k))throw Error('Presença inválida na cópia.');unique.add(k)}for(const n of s.notices)if(typeof n.body!=='string')throw Error('Aviso inválido.')}
function guardNavigation(callback){if(!dirty){callback();return}confirmDialog('Descartar alterações não salvas?','Há alterações nesta tela. Volte para salvar ou confirme para descartá-las.',()=>{dirty=false;$('#modal').close();callback()})}
function bind(){
 $$('[data-page]').forEach(b=>b.onclick=()=>guardNavigation(()=>{page=b.dataset.page;search='';viewClass='';render();window.scrollTo(0,0)}));
 $$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action));
 const cf=$('#class-filter');if(cf)cf.onchange=()=>{const value=cf.value;guardNavigation(()=>{viewClass=value;assessmentId='';render()});if(dirty)cf.value=viewClass};
 const af=$('#assessment-filter');if(af)af.onchange=()=>{const value=af.value;guardNavigation(()=>{assessmentId=value;render()});if(dirty)af.value=assessmentId};
 const ad=$('#attendance-date');if(ad)ad.onchange=()=>{const value=ad.value;if(!value){ad.value=attendanceDate;return}guardNavigation(()=>{attendanceDate=value;render()});if(dirty)ad.value=attendanceDate};
 const si=$('#search');if(si)si.oninput=()=>{search=si.value;const cursor=si.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(cursor,cursor)};
 $$('[data-grade],[data-grade-note]').forEach(i=>i.oninput=()=>dirty=true);
 $$('[data-attendance] button').forEach(b=>b.onclick=()=>{dirty=true;const row=b.parentElement;row.querySelectorAll('button').forEach(x=>{x.className='';x.setAttribute('aria-pressed','false')});if(b.dataset.status!=='clear'){b.className='selected-'+b.dataset.status;b.setAttribute('aria-pressed','true')}if(!row.querySelector('[data-status="clear"]')){const x=document.createElement('button');x.textContent='×';x.title='Limpar registro';x.setAttribute('aria-label','Limpar registro');x.onclick=()=>{row.querySelectorAll('button').forEach(b=>{b.className='';b.setAttribute('aria-pressed','false')});dirty=true};row.append(x)}});
 if($('#config-form'))$('#config-form').onsubmit=configure;
 if($('#backup-file'))$('#backup-file').onchange=e=>importBackup(e.target.files[0]);
}
async function handle(action){
 if(await handleRegistrationAction(action))return;
 if(await handleFinanceAction(action))return;
 if(await handleStudentAction(action))return;
 const [verb,id]=action.split(':');if(verb.startsWith('go-')){guardNavigation(()=>{page=verb.slice(3);search='';viewClass='';render()});return}
 if(verb.startsWith('new-')){guardNavigation(()=>editor(verb.slice(4)));return}
 if(verb.startsWith('edit-')){guardNavigation(()=>editor(verb.slice(5),id));return}
 if(verb.startsWith('delete-')){guardNavigation(()=>deletion(verb.slice(7),id));return}
 if(verb==='class-grade'){guardNavigation(()=>{viewClass=id;page='grades';render()});return}
 if(verb==='save-grades')return saveGrades();if(verb==='save-attendance')return saveAttendance();
 if(verb==='all-present'){$$('[data-attendance] [data-status="present"]').forEach(b=>b.click());return}
 if(verb==='export-backup')return backup();if(verb==='export-csv')return exportCSV();if(verb==='import-backup')return $('#backup-file').click();
 if(verb==='download-sql'){const r=await fetch('./schema.sql');if(!r.ok){toast('Não foi possível baixar o SQL.');return}download('trilha-apostolica-schema.sql',await r.text(),'text/plain');return}
 if(verb==='setup-help')return setupHelp();
 if(verb==='download-team-sql')return downloadTeamSQL();
 if(verb==='refresh-access')return refreshAccess();
 if(verb==='add-coordinator')return guardNavigation(addCoordinator);
 if(verb==='remove-coordinator')return guardNavigation(()=>removeCoordinator(id));
 if(verb==='more-menu')return moreMenu();
 if(verb==='logout')return guardNavigation(async()=>{const {error}=await client.auth.signOut();if(error){toast(friendly(error));return}session=null;resetCoordination();state=fresh();revision=null;loaded=false;render()});
 if(verb==='disconnect'&&deploymentConfig){toast('A conexão desta publicação é definida pela coordenação no Cloudflare.');return}
 if(verb==='disconnect')return confirmDialog('Desconectar este projeto?','O aplicativo voltará ao modo local. Os dados do Supabase não serão apagados. O acesso online poderá ser configurado novamente.',()=>{client?.auth.stopAutoRefresh();localStorage.removeItem(CONFIG);location.reload()});
}
function setupHelp(){const d=$('#modal');d.innerHTML=`<button class="close" aria-label="Fechar">×</button><h2>Conectar o Supabase</h2><ol class="install-steps"><li>Crie um projeto em <a href="https://supabase.com/dashboard" target="_blank" rel="noopener">supabase.com</a>.</li><li>No SQL Editor, execute o arquivo <a href="./schema.sql" download>schema.sql</a>.</li><li>Em Authentication → Users, crie seu usuário coordenador com e-mail confirmado.</li><li>Copie o ID desse usuário e execute a autorização indicada no fim do SQL.</li><li>Para permitir o cadastro dos alunos, habilite novos cadastros e confirmação de e-mail em Authentication → Sign In / Providers. Configure o endereço do app em URL Configuration.</li><li>Em Project Settings → API, copie a URL do projeto e a chave pública.</li><li>Preencha os campos do aplicativo e entre com seu e-mail e senha.</li></ol><div class="note">Se já cadastrou dados no modo local, exporte a cópia antes de conectar. Depois do login, importe essa cópia para gravar no Supabase.</div><button class="btn" id="help-close">Entendi</button>`;d.querySelector('.close').onclick=()=>d.close();$('#help-close').onclick=()=>d.close();d.showModal()}
function publicKey(key){return isPublicSupabaseKey(key)}
async function configure(e){e.preventDefault();if(deploymentConfig){toast('A conexão desta publicação é definida pela coordenação no Cloudflare.');return}const data=new FormData(e.currentTarget);const url=data.get('url').trim().replace(/\/$/,'');const key=data.get('key').trim();try{const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co')||u.pathname!=='/'||u.search||u.hash)throw Error('Use a URL HTTPS do projeto, no formato https://projeto.supabase.co.');if(!publicKey(key))throw Error('Use uma chave publishable ou anon válida. Chaves secretas não são aceitas.');const apply=()=>{localStorage.setItem(CONFIG,JSON.stringify({url,key}));location.reload()};if(state.students.length||state.classes.length)confirmDialog('Conectar o banco online?','Os dados locais não serão enviados automaticamente. Exporte uma cópia agora e importe depois de entrar no Supabase. Confirme se já guardou sua cópia.',apply);else apply()}catch(err){$('#config-error').textContent=friendly(err)}}
function renderLogin(error=''){ $('#app').innerHTML=`<main class="lock panel"><div class="brand"><img class="brand-logo" src="./brand-logo.svg" alt="Trilha Apostólica"></div><div class="eyebrow">SUA CONTA · SUA TRILHA</div><h1>Bom ter você aqui.</h1><p>Entre com sua conta para acessar seu espaço.</p><form id="login-form"><label>E-mail<input name="email" type="email" autocomplete="username" required></label><label>Senha<input name="password" type="password" autocomplete="current-password" required minlength="6"></label><p class="login-error" id="login-error" role="alert">${esc(error)}</p><button class="btn" type="submit">Entrar ${icon('arrow')}</button></form><div class="auth-switch">Ainda não tem conta? ${btn('Criar conta','auth-register','text')}</div><p class="small muted" style="margin-top:24px">Seu acesso é liberado pela coordenação. Use o e-mail e a senha da sua conta individual.</p>${deploymentConfig?'':`<div class="actions">${btn('Como configurar','setup-help','text')}${btn('Desconectar projeto','disconnect','text')}</div>`}</main>`;$$('[data-action]').forEach(b=>b.onclick=()=>handle(b.dataset.action));$('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const button=form.querySelector('button');button.disabled=true;$('#login-error').textContent='';try{const fd=new FormData(form);const {data,error}=await client.auth.signInWithPassword({email:fd.get('email').trim(),password:fd.get('password')});if(error)throw error;session=data.session;await load();page='home';render()}catch(err){session=null;loaded=false;$('#login-error').textContent=friendly(err);button.disabled=false}}}
async function start(){
 if(deploymentConfigError){$('#app').innerHTML=`<main class="lock panel"><h1>Conexão indisponível</h1><p>${esc(deploymentConfigError)}</p></main>`;return}
 if(acceptAccessLink())return;
 try{if(config){client=createClient(config.url,config.key,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data,error}=await client.auth.getSession();if(error)throw error;session=data.session;if(session){try{await load()}catch(e){session=null;renderLogin(friendly(e));return}}client.auth.onAuthStateChange((event,s)=>{if(event==='SIGNED_OUT'){session=null;resetCoordination();revision=null;state=fresh();loaded=false;render()}else if(s){session=s}})}else await load();render()}catch(e){$('#app').innerHTML=`<main class="lock panel"><h1>Não foi possível abrir os dados</h1><p>${esc(friendly(e))}</p><button class="btn" id="retry">Tentar novamente</button>${config&&!deploymentConfig?'<button class="btn secondary" id="reset-config">Desconectar projeto</button>':''}</main>`;$('#retry').onclick=()=>location.reload();if($('#reset-config'))$('#reset-config').onclick=()=>{localStorage.removeItem(CONFIG);location.reload()}}}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
start();

window.addEventListener('storage',e=>{if(e.key===KEY&&local()){if(dirty){toast('Outra janela alterou os dados. Exporte sua cópia antes de recarregar.')}else{load().then(render).catch(err=>toast(friendly(err)))}}});
